import std.collection.HashMap
import std.collection.Option
import std.time.DateTime
import std.log.Logger

class AccessGatewayFilter {
    let logger: Logger = Logger()

    public init() {
    }

    public func filter(request: HashMap<String, Any>): Bool {
        let request_uri = request["path"] as String
        let method = request["method"] as String

        if (this.is_start_with(request_uri)) {
            return true
        }

        match (this.get_jwt_user(request)) {
            case Some(token) => {
                let user = token["user"] as HashMap<String, Any>
                if ((user["level"] as Int64) > 2) {
                    this.set_current_user_info_and_log(user)
                    return true
                }
            }
            case None => {}
        }
        return false
    }

    public func is_start_with(request_uri: String): Bool {
        let prefixes = ["/api", "/login"]
        for (prefix in prefixes) {
            if (request_uri.startsWith(prefix)) {
                return true
            }
        }
        return false
    }

    public func get_jwt_user(request: HashMap<String, Any>): Option<HashMap<String, Any>> {
        let headers = request["headers"] as HashMap<String, Any>
        let token_map = headers["Authorization"] as HashMap<String, Any>
        let user = token_map["user"] as HashMap<String, Any>
        let jwt = token_map["jwt"] as String

        if (jwt.startsWith((user["name"] as String))) {
            let parts = jwt.split((user["name"] as String))
            if (parts.size == 2) {
                let jwt_str_date = parts[1]
                match (DateTime.fromString(jwt_str_date, "yyyy-MM-dd")) {
                    case Some(jwt_date) => {
                        let today = DateTime.now()
                        let diff = today - jwt_date
                        if (diff.inDays() < 3) {
                            return Some(token_map)
                        }
                    }
                    case None => {}
                }
            }
        }
        return None
    }

    public func set_current_user_info_and_log(user: HashMap<String, Any>): Unit {
        let name = user["name"] as String
        let host = user["address"] as String
        let msg = "${name}${host}${DateTime.now().toString("yyyy-MM-dd HH:mm:ss")}"
        this.logger.log(msg, level: 1)
    }
}

import std.math.*

class AreaCalculator {
    let radius: Float64

    public init(radius: Float64) {
        this.radius = radius
    }

    public func calculate_circle_area(): Float64 {
        return PI * radius ** 2
    }

    public func calculate_sphere_area(): Float64 {
        return 4 * PI * radius ** 2
    }

    public func calculate_cylinder_area(height: Float64): Float64 {
        return 2 * PI * radius * (radius + height)
    }

    public func calculate_sector_area(angle: Float64): Float64 {
        return radius ** 2 * angle / 2
    }

    public func calculate_annulus_area(inner_radius: Float64, outer_radius: Float64): Float64 {
        return PI * (outer_radius ** 2 - inner_radius ** 2)
    }
}

