class ArgumentParser {
    let arguments: HashMap<String, Any>
    let required: HashSet<String>
    let types: HashMap<String, TypeInfo>

    public init() {
        arguments = HashMap<String, Any>()
        required = HashSet<String>()
        types = HashMap<String, TypeInfo>()
    }

    public func parse_arguments(command_string: String): (Bool, Option<HashSet<String>>) {
        var args = ArrayList<String>([])
        var parsing = false
        var current_arg = ""

        // Split command string into arguments (simplified splitting - in real use, might need more robust parsing)
        for part in command_string.split() {
            if part == "script.py" || part == "python" {
                continue // skip script and python keywords
            }
            if part.startsWith("--") {
                if parsing {
                    // Previous arg was a flag without value
                    arguments.add(current_arg, true)
                }
                let kv = part[2..].split("=")
                if kv.size == 2 {
                    let converted = convert_type(kv[0], kv[1])
                    arguments.add(kv[0], converted)
                } else {
                    arguments.add(part[2..], true)
                }
                parsing = false
            } else if part.startsWith("-") {
                if parsing {
                    // Previous arg was a flag without value
                    arguments.add(current_arg, true)
                }
                current_arg = part[1..]
                parsing = true
            } else {
                if parsing {
                    let converted = convert_type(current_arg, part)
                    arguments.add(current_arg, converted)
                    parsing = false
                    current_arg = ""
                } else {
                    // Handle positional args if needed (though Python example doesn't show them)
                    // For this implementation, we'll ignore unexpected positional args
                }
            }
        }

        // Handle case where last arg was a flag without following value
        if parsing {
            arguments.add(current_arg, true)
        }

        let missing = required.filter({r => !arguments.contains(r)})
        if missing.size > 0 {
            let missing_set = HashSet<String>()
            for arg in missing {
                missing_set.add(arg)
            }
            return (false, Some<HashSet<String>>(missing_set))
        }
        return (true, None<HashSet<String>>)
    }

    public func get_argument(key: String): Any {
        return arguments.get(key) ?? None<Any>()
    }

    public func add_argument(arg: String, required!: Bool = false, arg_type!: TypeInfo = TypeInfo.of<String>()): Unit {
        types.add(arg, arg_type)
        if required {
            required.add(arg)
        }
    }

    public func convert_type(arg: String, value: String): Any {
        match (types.get(arg)) {
            case Some(ti) => 
                match (ti.name) {
                    case "Int64" => return value.toInt64() ?? value
                    case "Float64" => return value.toFloat64() ?? value
                    case "Bool" => 
                        match (value.toLowerCase()) {
                            case "true" => return true
                            case "false" => return false
                            case _ => return value
                        }
                    case _ => return value
                }
            case _ => return value
        }
    }
}

import std.collection.ArrayList

class ArrangementCalculator {
    let datas: ArrayList<Int64>

    public init(datas: ArrayList<Int64>) {
        this.datas = datas
    }

    public static func count(n: Int64, m: Option<Int64>): Int64 {
        let mm = m ?? n
        if (mm < 0 || mm > n) {
            return 0
        }
        // Calculate arrangements P(n,m) = n! / (n-m)!
        let numerator = factorial(n)
        let denominator = factorial(n - mm)
        return numerator / denominator
    }

    public static func count_all(n: Int64): Int64 {
        var total: Int64 = 0
        for (i in 1..n+1) {
            total += count(n, Some(i))
        }
        return total
    }

    public func select(m: Option<Int64>): ArrayList<ArrayList<Int64>> {
        let mm = m ?? datas.size.toInt64()
        if (mm < 0 || mm > datas.size.toInt64()) {
            return ArrayList<ArrayList<Int64>>()
        }
        let result = ArrayList<ArrayList<Int64>>()
        select_permutations(ArrayList<Int64>(), datas, mm, result)
        return result
    }

    public func select_all(): ArrayList<ArrayList<Int64>> {
        let result = ArrayList<ArrayList<Int64>>()
        for (i in 1..datas.size+1) {
            result.extend(select(Some(i.toInt64())))
        }
        return result
    }

    public static func factorial(n: Int64): Int64 {
        if (n <= 1) {
            return 1
        }
        var result: Int64 = 1
        for (i in 2..n+1) {
            result *= i
        }
        return result
    }

    private func select_permutations(prefix: ArrayList<Int64>, remaining: ArrayList<Int64>, m: Int64, result: ArrayList<ArrayList<Int64>>): Unit {
        if (prefix.size == m) {
            result.add(ArrayList<Int64>(prefix))
            return
        }
        for (i in 0..remaining.size) {
            let new_prefix = ArrayList<Int64>(prefix)
            new_prefix.add(remaining[i])
            let new_remaining = ArrayList<Int64>(remaining)
            new_remaining.remove(at: i)
            select_permutations(new_prefix, new_remaining, m, result)
        }
    }
}

