class AutomaticGuitarSimulator {

    let play_text: String

    public init(text: String) {
        this.play_text = text
    }

    public func interpret(display!: Bool = false): ArrayList<HashMap<String, String>> {
        if (this.play_text.strip().size == 0) {
            return ArrayList<HashMap<String, String>>()
        }

        var play_list = ArrayList<HashMap<String, String>>()
        let play_segs = this.play_text.split(" ")
        for (play_seg in play_segs) {
            var pos = 0
            for (i in 0..play_seg.size) {
                let ele = play_seg[i]
                if (ele.isAlpha()) {
                    pos += 1
                    continue
                }
                break
            }
            let play_chord = play_seg.substring(0, pos)
            let play_value = play_seg.substring(pos)

            let entry = HashMap<String, String>([("Chord", play_chord), ("Tune", play_value)])
            play_list.add(entry)

            if (display) {
                this.display(key: play_chord, value: play_value)
            }
        }
        return play_list
    }

    public func display(key: String, value: String): String {
        return "Normal Guitar Playing -- Chord: ${key}, Play Tune: ${value}"
    }
}

import std.collection.ArrayList

class AvgPartition {
    let lst: ArrayList<Int64>
    let limit: Int64

    public init(lst: ArrayList<Int64>, limit: Int64) {
        this.lst = lst
        this.limit = limit
    }

    public func setNum(): (Int64, Int64) {
        let size = lst.size / limit
        let remainder = lst.size % limit
        return (size, remainder)
    }

    public func get(index: Int64): ArrayList<Int64> {
        let (size, remainder) = this.setNum()
        let start = index * size + min(index, remainder.to<Int64>())
        var end = start + size
        if index + 1 <= remainder.to<Int64>() {
            end += 1
        }

        let result = ArrayList<Int64>()
        for (i in start..end) {
            if (i < lst.size) {  // Handle edge case where index is out of bounds
                result.add(lst[i])
            }
        }
        return result
    }
}

import std.collection.ArrayList

class BalancedBrackets {
    let stack: ArrayList<String>
    let left_brackets: ArrayList<String>
    let right_brackets: ArrayList<String>
    var expr: String

    public init(expr: String) {
        this.stack = ArrayList<String>()
        this.left_brackets = ArrayList<String>(["(", "{", "["])
        this.right_brackets = ArrayList<String>([")", "}", "]"])
        this.expr = expr
    }

    public func clear_expr(): Unit {
        var filtered_chars = ArrayList<Rune>()
        for c in this.expr.runes() {
            let char_str = String.fromRune(c)
            if (this.left_brackets.contains(char_str) || 
                this.right_brackets.contains(char_str)) {
                filtered_chars.add(c)
            }
        }
        this.expr = String.fromRuneArray(filtered_chars.toRuneArray())
    }

    public func check_balanced_brackets(): Bool {
        this.clear_expr()
        for c in this.expr.runes() {
            let char_str = String.fromRune(c)
            if (this.left_brackets.contains(char_str)) {
                this.stack.add(char_str)
            } else {
                if (this.stack.size == 0) {
                    return false
                }
                let current_bracket = this.stack.remove(at: this.stack.size - 1)
                match (current_bracket) {
                    case "(" => if (char_str != ")") { return false }
                    case "{" => if (char_str != "}") { return false }
                    case "[" => if (char_str != "]") { return false }
                    case _ => return false
                }
            }
        }
        return this.stack.size == 0
    }
}

import std.exception.*

class BankAccount {
    var balance: Int64

    public init(balance!: Int64 = 0) {
        this.balance = balance
    }

    public func deposit(amount: Int64): Int64 {
        if (amount < 0) {
            throw Exception("Invalid amount")
        }
        this.balance += amount
        return this.balance
    }

    public func withdraw(amount: Int64): Int64 {
        if (amount < 0) {
            throw Exception("Invalid amount")
        }
        if (amount > this.balance) {
            throw Exception("Insufficient balance.")
        }
        this.balance -= amount
        return this.balance
    }

    public func view_balance(): Int64 {
        return this.balance
    }

    public func transfer(other_account: BankAccount, amount: Int64): Unit {
        this.withdraw(amount: amount)
        other_account.deposit(amount: amount)
    }
}

