import std.collection.ArrayList

class BoyerMooreSearch {
    let text: String
    let pattern: String
    let textLen: Int64
    let patLen: Int64

    public init(text: String, pattern: String) {
        this.text = text
        this.pattern = pattern
        this.textLen = text.size
        this.patLen = pattern.size
    }

    public func match_in_pattern(char: String): Int64 {
        for (i in (this.patLen - 1)..0:-1) {
            if (this.pattern[i] == char[0]) { // Compare first character of String
                return i
            }
        }
        return -1
    }

    public func mismatch_in_text(currentPos: Int64): Int64 {
        for (i in (this.patLen - 1)..0:-1) {
            if (this.currentPos + i >= this.textLen) {
                return this.currentPos + i
            }
            if (this.pattern[i] != this.text[currentPos + i]) {
                return currentPos + i
            }
        }
        return -1
    }

    public func bad_character_heuristic(): ArrayList<Int64> {
        let positions = ArrayList<Int64>([])
        var i: Int64 = 0
        while (i <= this.textLen - this.patLen) {
            let mismatch_index = this.mismatch_in_text(i)
            if (mismatch_index == -1) {
                positions.add(i)
                i += 1
            } else {
                let char_to_match = String([this.text[mismatch_index]]) // Convert Rune to String
                let match_index = this.match_in_pattern(char_to_match)
                if (match_index == -1) {
                    i = mismatch_index + 1
                } else {
                    i = mismatch_index - match_index + 1
                }
            }
        }
        return positions
    }
}

import std.collection.HashMap
import std.collection.ArrayList
import std.convert.Parsable

class Calculator {
    let operators: HashMap<String, (Float64, Float64) -> Float64>

    public init() {
        this.operators = HashMap<String, (Float64, Float64) -> Float64>([
            ("+", {x: Float64, y: Float64 => x + y}),
            ("-", {x: Float64, y: Float64 => x - y}),
            ("*", {x: Float64, y: Float64 => x * y}),
            ("/", {x: Float64, y: Float64 => x / y}),
            ("^", {x: Float64, y: Float64 => x ** y})
        ])
    }

    public func calculate(expression: String): Option<Float64> {
        let operand_stack = ArrayList<Float64>()
        let operator_stack = ArrayList<String>()
        var num_buffer = ""
        var char_index = 0

        while (char_index < expression.size) {
            let c = expression[char_index] as Rune
            if isNumber(c) || c == r'.' {
                num_buffer += c.toString()
            } else {
                if num_buffer != "" {
                    if let num = num_buffer.parse<Float64>() {
                        operand_stack.add(num)
                    } else {
                        return None<Float64>()
                    }
                    num_buffer = ""
                }

                if contains(c, ['+', '-', '*', '/', '^']) {
                    while (operator_stack.size > 0 && 
                           operator_stack[operator_stack.size - 1] != "(" && 
                           precedence(operator_stack[operator_stack.size - 1]) >= precedence(c.toString())) {
                        (operand_stack, operator_stack) = apply_operator(operand_stack, operator_stack)
                    }
                    operator_stack.add(c.toString())
                } else if c == r'(' {
                    operator_stack.add(c.toString())
                } else if c == r')' {
                    while (operator_stack.size > 0 && operator_stack[operator_stack.size - 1] != "(") {
                        (operand_stack, operator_stack) = apply_operator(operand_stack, operator_stack)
                    }
                    if operator_stack.size > 0 {
                        operator_stack.remove(at: operator_stack.size - 1)
                    } else {
                        return None<Float64>()
                    }
                }
            }
            char_index += 1
        }

        if num_buffer != "" {
            if let num = num_buffer.parse<Float64>() {
                operand_stack.add(num)
            } else {
                return None<Float64>()
            }
        }

        while (operator_stack.size > 0) {
            (operand_stack, operator_stack) = apply_operator(operand_stack, operator_stack)
        }

        if operand_stack.size == 1 {
            return Some<Float64>(operand_stack[0])
        } else {
            return None<Float64>()
        }
    }

    public func precedence(op: String): Int64 {
        match (op) {
            case "+" => 1
            case "-" => 1
            case "*" => 2
            case "/" => 2
            case "^" => 3
            case _ => 0
        }
    }

    public func apply_operator(operand_stack: ArrayList<Float64>, operator_stack: ArrayList<String>): (ArrayList<Float64>, ArrayList<String>) {
        if operator_stack.size == 0 || operand_stack.size < 2 {
            return (operand_stack, operator_stack)
        }

        let op = operator_stack[operator_stack.size - 1]
        operator_stack.remove(at: operator_stack.size - 1)

        let op2 = operand_stack[operand_stack.size - 1]
        operand_stack.remove(at: operand_stack.size - 1)
        let op1 = operand_stack[operand_stack.size - 1]
        operand_stack.remove(at: operand_stack.size - 1)

        let result = operators[op].getOrThrow()(op1, op2)
        operand_stack.add(result)

        return (operand_stack, operator_stack)
    }
}

// Helper function (not part of the class)
func isNumber(c: Rune): Bool {
    match (c) {
        case r'0'..r'9' => true
        case _ => false
    }
}

func contains<T>(c: Rune, items: ArrayList<T>): Bool {
    let str_c = c.toString()
    for item in items {
        if item as String == str_c {
            return true
        }
    }
    return false
}

