class CalendarUtil {
    let events: ArrayList<Event>

    public init() {
        this.events = ArrayList<Event>()
    }

    public func add_event(event: Event): Unit {
        this.events.add(event)
    }

    public func remove_event(event: Event): Unit {
        var index = -1
        for (i in 0..this.events.size) {
            if (this.events[i] == event) {
                index = i
                break
            }
        }
        if (index != -1) {
            this.events.remove(at: index)
        }
    }

    public func get_events(date: DateTime): ArrayList<Event> {
        let events_on_date = ArrayList<Event>()
        for (event in this.events) {
            if (event.start_time.date() == date.date()) {
                events_on_date.add(event)
            }
        }
        return events_on_date
    }

    public func is_available(start_time: DateTime, end_time: DateTime): Bool {
        for (event in this.events) {
            if (start_time.before(event.end_time) && end_time.after(event.start_time)) {
                return false
            }
        }
        return true
    }

    public func get_available_slots(date: DateTime): ArrayList<(DateTime, DateTime)> {
        let available_slots = ArrayList<(DateTime, DateTime)>()
        let start_time = DateTime.of(year: date.year(), month: date.month(), dayOfMonth: date.dayOfMonth(), hour: 0, minute: 0)
        let end_time = DateTime.of(year: date.year(), month: date.month(), dayOfMonth: date.dayOfMonth(), hour: 23, minute: 59)

        var current = start_time
        while (current.before(end_time)) {
            let slot_end = current.add(hours: 1)
            if (this.is_available(current, slot_end)) {
                available_slots.add((current, slot_end))
            }
            current = slot_end
        }
        return available_slots
    }

    public func get_upcoming_events(num_events: Int64): ArrayList<Event> {
        let upcoming_events = ArrayList<Event>()
        let now = DateTime.now()
        for (event in this.events) {
            if (event.start_time.after(now)) {
                upcoming_events.add(event)
            }
            if (upcoming_events.size == num_events) {
                break
            }
        }
        return upcoming_events
    }
}

import std.collection.HashMap

class CamelCaseMap {

    let _data: HashMap<String, Any>

    public init() {
        _data = HashMap<String, Any>()
    }

    public func __getitem__(key: String): Any {
        let converted_key = this._convert_key(key)
        match (_data.get(converted_key)) {
            case Some(value) => return value
            case None => {
                // In Cangjie, we don't have explicit exception throwing like Python,
                // but we could return a default or handle error differently
                // For this implementation, we'll just crash (similar to Python's KeyError)
                panic("Key not found: ${key}")
            }
        }
    }

    public func __setitem__(key: String, value: Any): Unit {
        let converted_key = this._convert_key(key)
        _data.add(converted_key, value)
    }

    public func __delitem__(key: String): Unit {
        let converted_key = this._convert_key(key)
        match (_data.get(converted_key)) {
            case Some(_) => _data.remove(converted_key)
            case None => panic("Key not found: ${key}")
        }
    }

    public func __len__(): Int64 {
        return _data.size
    }

    public func _convert_key(key: Any): String {
        match (key) {
            case s: String => return this._to_camel_case(s)
            case _ => return "${key}" // Fallback to string conversion for other types
        }
    }

    public static func _to_camel_case(key: String): String {
        let parts = key.split('_')
        if (parts.size == 0) {
            return ""
        }
        var result = parts[0]
        for (i in 1..parts.size) {
            let part = parts[i]
            if (part.size > 0) {
                let first = part[0].upper()
                let rest = part[1..part.size]
                result += first + rest
            }
        }
        return result
    }
}

import std.collection.ArrayList

class ChandrasekharSieve {
    let n: Int64
    var primes: ArrayList<Int64> = ArrayList<Int64>()

    public init(n: Int64) {
        this.n = n
        this.primes = this.generate_primes()
    }

    public func generate_primes(): ArrayList<Int64> {
        if (this.n < 2) {
            return ArrayList<Int64>([])
        }

        var sieve = ArrayList<Bool>([true; this.n.toInt() + 1])
        sieve[0] = false
        sieve[1] = false

        var p: Int64 = 2
        while (p * p <= this.n) {
            if (sieve[p.toInt()]) {
                let p_sq = p * p
                for (i in p_sq.toInt()..this.n.toInt()+1:p.toInt()) {
                    sieve[i] = false
                }
            }
            p = p + 1
        }

        var result = ArrayList<Int64>([])
        for (i in 2..this.n.toInt()+1:1) {
            if (sieve[i]) {
                result.add(i.toInt64())
            }
        }

        return result
    }

    public func get_primes(): ArrayList<Int64> {
        return this.primes
    }
}

