class CurrencyConverter {

    let rates: HashMap<String, Float64>

    public init() {
        this.rates = HashMap<String, Float64>()
        this.rates.add('USD', 1.0)
        this.rates.add('EUR', 0.85)
        this.rates.add('GBP', 0.72)
        this.rates.add('JPY', 110.15)
        this.rates.add('CAD', 1.23)
        this.rates.add('AUD', 1.34)
        this.rates.add('CNY', 6.40)
    }

    public func convert(amount: Float64, from_currency: String, to_currency: String): Float64 {
        if (from_currency == to_currency) {
            return amount
        }

        if (!this.rates.contains(from_currency) || !this.rates.contains(to_currency)) {
            return 0.0 // In Python version returns False, but Cangjie needs Float64 return type
        }

        let from_rate = this.rates[from_currency] ?? 0.0
        let to_rate = this.rates[to_currency] ?? 0.0

        let converted_amount = (amount / from_rate) * to_rate
        return converted_amount
    }

    public func get_supported_currencies(): ArrayList<String> {
        let currencies = ArrayList<String>()
        for (currency in this.rates.keys()) {
            currencies.add(currency)
        }
        return currencies
    }

    public func add_currency_rate(currency: String, rate: Float64): Bool {
        if (this.rates.contains(currency)) {
            return false
        }
        this.rates.add(currency, rate)
        return true
    }

    public func update_currency_rate(currency: String, new_rate: Float64): Bool {
        if (!this.rates.contains(currency)) {
            return false
        }
        this.rates[currency] = new_rate
        return true
    }
}

import std.collection.HashMap
import std.collection.ArrayList
import std.math.round
import std.sort.sort

class DataStatistics {

    public func mean(data: ArrayList<Int64>): Float64 {
        var sum: Int64 = 0
        for (i in 0..data.size) {
            sum = sum + data[i]
        }
        let mean_value = Float64(sum) / Float64(data.size)
        return round(mean_value * 100) / 100
    }

    public func median(data: ArrayList<Int64>): Float64 {
        let sorted_data = ArrayList<Int64>(data)
        sort(sorted_data)
        let n = data.size
        if (n % 2 == 0) {
            let middle = n / 2
            let a = sorted_data[middle - 1]
            let b = sorted_data[middle]
            let median_value = (Float64(a) + Float64(b)) / 2
            return round(median_value * 100) / 100
        } else {
            let middle = n / 2
            let median_value = sorted_data[middle]
            return Float64(median_value)
        }
    }

    public func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        let freq_map = HashMap<Int64, Int64>()
        for (i in 0..data.size) {
            let num = data[i]
            let count = if (freq_map.contains(num)) {
                freq_map[num]!! + 1
            } else {
                1
            }
            freq_map.add(num, count)
        }

        var max_count: Int64 = 0
        for (num in freq_map.keys) {
            let count = freq_map[num]!!
            if (count > max_count) {
                max_count = count
            }
        }

        let modes = ArrayList<Int64>()
        for (num in freq_map.keys) {
            if (freq_map[num]!! == max_count) {
                modes.add(num)
            }
        }

        // Sort modes for consistent output
        sort(modes)
        return modes
    }
}

