        let mean: Float64 = this.get_sum() / Float64(this.data.size)
        var sum_sq_diff: Float64 = 0.0
        for (i in 0..<this.data.size) {
            sum_sq_diff += (this.data[i] - mean) * (this.data[i] - mean)
        }
