import std.collection.ArrayList
import std.math.sqrt
import std.math.exp
import std.math.pow
import std.math.PI

class DataStatistics4 {

    public static func correlation_coefficient(data1: ArrayList<Float64>, data2: ArrayList<Float64>): Float64 {
        let n = data1.size
        var sum1: Float64 = 0.0
        var sum2: Float64 = 0.0

        for (i in 0..n) {
            sum1 += data1[i]
            sum2 += data2[i]
        }

        let mean1 = sum1 / n.toFloat64()
        let mean2 = sum2 / n.toFloat64()

        var numerator: Float64 = 0.0
        var sum_sq1: Float64 = 0.0
        var sum_sq2: Float64 = 0.0

        for (i in 0..n) {
            let diff1 = data1[i] - mean1
            let diff2 = data2[i] - mean2
            numerator += diff1 * diff2
            sum_sq1 += diff1 * diff1
            sum_sq2 += diff2 * diff2
        }

        let denominator = sqrt(sum_sq1) * sqrt(sum_sq2)
        return if (denominator != 0.0) { numerator / denominator } else { 0.0 }
    }

    public static func skewness(data: ArrayList<Float64>): Float64 {
        let n = data.size
        var sum_x: Float64 = 0.0

        for (i in 0..n) {
            sum_x += data[i]
        }

        let mean = sum_x / n.toFloat64()

        var sum_sq: Float64 = 0.0
        for (i in 0..n) {
            let diff = data[i] - mean
            sum_sq += diff * diff
        }

        let variance = sum_sq / n.toFloat64()
        let std_deviation = sqrt(variance)

        if (std_deviation == 0.0) {
            return 0.0
        }

        var sum_cube: Float64 = 0.0
        for (i in 0..n) {
            let diff = data[i] - mean
            sum_cube += diff * diff * diff
        }

        let skewness = (sum_cube * n.toFloat64()) / ((n.toFloat64() - 1.0) * (n.toFloat64() - 2.0) * pow(std_deviation, 3))
        return skewness
    }

    public static func kurtosis(data: ArrayList<Float64>): Float64 {
        let n = data.size
        var sum_x: Float64 = 0.0

        for (i in 0..n) {
            sum_x += data[i]
        }

        let mean = sum_x / n.toFloat64()

        var sum_sq: Float64 = 0.0
        for (i in 0..n) {
            let diff = data[i] - mean
            sum_sq += diff * diff
        }

        let std_dev = sqrt(sum_sq / n.toFloat64())

        if (std_dev == 0.0) {
            return Float64.nan // Cangjie doesn't have direct NaN support, this might need adjustment
        }

        var sum_fourth: Float64 = 0.0
        for (i in 0..n) {
            let diff = data[i] - mean
            sum_fourth += diff * diff * diff * diff
        }

        let fourth_moment = sum_fourth / n.toFloat64()
        let kurtosis_value = (fourth_moment / pow(std_dev, 4)) - 3.0
        return kurtosis_value
    }

    public static func pdf(data: ArrayList<Float64>, mu: Float64, sigma: Float64): ArrayList<Float64> {
        let result = ArrayList<Float64>()
        let coefficient = 1.0 / (sigma * sqrt(2.0 * PI))

        for (i in 0..data.size) {
            let x = data[i]
            let exponent = -0.5 * pow((x - mu) / sigma, 2)
            let pdf_value = coefficient * exp(exponent)
            result.add(pdf_value)
        }

        return result
    }
}

import std.collection.ArrayList

class DecryptionUtils {
    let key: String

    public init(key: String) {
        this.key = key
    }

    public func caesar_decipher(ciphertext: String, shift: Int64): String {
        var plaintext = ""
        for c in ciphertext.runes() {
            let char = c.toChar()
            if char.isAlpha() {
                let ascii_offset = if (char.isUpper()) { 65 } else { 97 }
                let shifted_char = (char.toInt() - ascii_offset - shift % 26 + 26) % 26 + ascii_offset
                plaintext += String.fromCharCode(shifted_char)
            } else {
                plaintext += char
            }
        }
        return plaintext
    }

    public func vigenere_decipher(ciphertext: String): String {
        var decrypted_text = ""
        var key_index = 0
        for c in ciphertext.runes() {
            let char = c.toChar()
            if char.isAlpha() {
                let key_char = this.key[key_index % this.key.size].toLower()
                let shift = key_char.toInt() - 'a'.toInt()
                let decrypted_char = (char.toLower().toInt() - 'a'.toInt() - shift + 26) % 26 + 'a'.toInt()
                decrypted_text += if (char.isUpper()) { 
                    String.fromCharCode(decrypted_char).toUpper() 
                } else { 
                    String.fromCharCode(decrypted_char) 
                }
                key_index += 1
            } else {
                decrypted_text += char
            }
        }
        return decrypted_text
    }

    public func rail_fence_decipher(encrypted_text: String, rails: Int64): String {
        if rails <= 1 {
            return encrypted_text
        }

        // Calculate total length
        let len = encrypted_text.size

        // Initialize rail positions
        let positions = ArrayList<Int64>()
        var direction = -1
        var row = 0
        var rail_positions = ArrayList<ArrayList<Int64>>()
        for _ in 0..rails {
            rail_positions.add(ArrayList<Int64>([]))
        }

        // Mark rail positions without filling characters
        for _ in 0..len {
            if row == 0 || row == rails - 1 {
                direction = -direction
            }
            rail_positions[row].add(rail_positions[row].size.toInt64()) // Just track position order
            row += direction
        }

        // Reconstruct the actual positions (this approach needs adjustment for Cangjie)
        // Alternative implementation that works without complex position tracking:
        var rail_chars = ArrayList<ArrayList<Rune>>()
        for _ in 0..rails {
            rail_chars.add(ArrayList<Rune>([]))
        }

        // First pass: determine character distribution pattern
        var pattern = ArrayList<Int64>([])
        direction = -1
        row = 0
        for _ in 0..len {
            if row == 0 || row == rails - 1 {
                direction = -direction
            }
            pattern.add(row)
            row += direction
        }

        // Second pass: distribute characters according to pattern
        var char_index = 0
        for i in 0..len {
            rail_chars[pattern[i]].add(encrypted_text[i])
        }

        // Third pass: read characters in zigzag order
        var plain_text = ""
        var rail_indices = ArrayList<Int64>()
        for _ in 0..rails {
            rail_indices.add(0)
        }

        var current_row = 0
        direction = -1
        for _ in 0..len {
            if current_row == 0 || current_row == rails - 1 {
                direction = -direction
            }
            plain_text += rail_chars[current_row][rail_indices[current_row]].toChar()
            rail_indices[current_row] += 1
            current_row += direction
        }

        return plain_text
    }
}

