import std.collection.ArrayList
import std.collection.HashSet

class EightPuzzle {
    let initial_state: ArrayList<ArrayList<Int64>>
    let goal_state: ArrayList<ArrayList<Int64>>

    public init(initial_state: ArrayList<ArrayList<Int64>>) {
        this.initial_state = initial_state
        this.goal_state = ArrayList<ArrayList<Int64>>([
            ArrayList<Int64>([1, 2, 3]),
            ArrayList<Int64>([4, 5, 6]),
            ArrayList<Int64>([7, 8, 0])
        ])
    }

    public func find_blank(state: ArrayList<ArrayList<Int64>>): (Int64, Int64) {
        for (i in 0..3) {
            for (j in 0..3) {
                if (state[i][j] == 0) {
                    return (i, j)
                }
            }
        }
        return (-1, -1) // should never happen for valid states
    }

    private func copy_state(state: ArrayList<ArrayList<Int64>>): ArrayList<ArrayList<Int64>> {
        let new_state = ArrayList<ArrayList<Int64>>()
        for (row in state) {
            let new_row = ArrayList<Int64>()
            for (num in row) {
                new_row.add(num)
            }
            new_state.add(new_row)
        }
        return new_state
    }

    public func move(state: ArrayList<ArrayList<Int64>>, direction: String): ArrayList<ArrayList<Int64>> {
        let (i, j) = this.find_blank(state: state)
        var new_state = this.copy_state(state: state)

        match (direction) {
            case "up" => 
                if (i > 0) {
                    let temp = new_state[i-1][j]
                    new_state[i-1][j] = new_state[i][j]
                    new_state[i][j] = temp
                }
            case "down" => 
                if (i < 2) {
                    let temp = new_state[i+1][j]
                    new_state[i+1][j] = new_state[i][j]
                    new_state[i][j] = temp
                }
            case "left" => 
                if (j > 0) {
                    let temp = new_state[i][j-1]
                    new_state[i][j-1] = new_state[i][j]
                    new_state[i][j] = temp
                }
            case "right" => 
                if (j < 2) {
                    let temp = new_state[i][j+1]
                    new_state[i][j+1] = new_state[i][j]
                    new_state[i][j] = temp
                }
        }
        return new_state
    }

    public func get_possible_moves(state: ArrayList<ArrayList<Int64>>): ArrayList<String> {
        let (i, j) = this.find_blank(state: state)
        let moves = ArrayList<String>()

        if (i > 0) {
            moves.add("up")
        }
        if (i < 2) {
            moves.add("down")
        }
        if (j > 0) {
            moves.add("left")
        }
        if (j < 2) {
            moves.add("right")
        }
        return moves
    }

    private func state_equals(a: ArrayList<ArrayList<Int64>>, b: ArrayList<ArrayList<Int64>>): Bool {
        for (i in 0..3) {
            for (j in 0..3) {
                if (a[i][j] != b[i][j]) {
                    return false
                }
            }
        }
        return true
    }

    public func solve(): ArrayList<String> {
        // Tuple of (state, path)
        let open_list = ArrayList<((ArrayList<ArrayList<Int64>>, ArrayList<String>))>([
            (this.initial_state, ArrayList<String>())
        ])
        let closed_set = HashSet<ArrayList<ArrayList<Int64>>>()

        while (open_list.size > 0) {
            let (current_state, path) = open_list.remove(at: 0)
            closed_set.add(current_state)

            if (this.state_equals(a: current_state, b: this.goal_state)) {
                return path
            }

            let moves = this.get_possible_moves(state: current_state)
            for (move in moves) {
                let new_state = this.move(state: current_state, direction: move)
                if (!closed_set.contains(new_state)) {
                    let new_path = ArrayList<String>(path)
                    new_path.add(move)
                    open_list.add((new_state, new_path))
                }
            }
        }
        return ArrayList<String>() // no solution found
    }
}

import std.time.DateTime
import std.collection.ArrayList
import std.collection.HashMap

class EmailClient {

    let addr: String
    let capacity: Int64
    var inbox: ArrayList<HashMap<String, Any>>

    public init(addr: String, capacity: Int64) {
        this.addr = addr
        this.capacity = capacity
        this.inbox = ArrayList<HashMap<String, Any>>()
    }

    public func send_to(recv: EmailClient, content: String, size: Int64): Bool {
        if (!recv.is_full_with_one_more_email(size: size)) {
            let timestamp = DateTime.now().format("%Y-%m-%d %H:%M:%S")
            let email = HashMap<String, Any>([
                ("sender", this.addr),
                ("receiver", recv.addr),
                ("content", content),
                ("size", size),
                ("time", timestamp),
                ("state", "unread")
            ])
            recv.inbox.add(email)
            return true
        } else {
            this.clear_inbox(size: size)
            return false
        }
    }

    public func fetch(): HashMap<String, Any> {
        if (this.inbox.size == 0) {
            return HashMap<String, Any>() // Return empty map as None equivalent
        }
        for (i in 0..this.inbox.size) {
            let email = this.inbox.get(i) ?? HashMap<String, Any>()
            let state: String = email.get("state") ?? ""
            if (state == "unread") {
                email.put("state", "read")
                return email
            }
        }
        return HashMap<String, Any>()
    }

    public func is_full_with_one_more_email(size: Int64): Bool {
        let occupied_size = this.get_occupied_size()
        return occupied_size + size > this.capacity
    }

    public func get_occupied_size(): Int64 {
        var occupied_size: Int64 = 0
        for (i in 0..this.inbox.size) {
            let email = this.inbox.get(i) ?? HashMap<String, Any>()
            let size: Int64 = email.get("size") ?? 0
            occupied_size += size
        }
        return occupied_size
    }

    public func clear_inbox(size: Int64): Unit {
        if (this.addr.size == 0) {
            return
        }
        var freed_space: Int64 = 0
        while (freed_space < size && this.inbox.size > 0) {
            let email = this.inbox.get(0) ?? HashMap<String, Any>()
            let email_size: Int64 = email.get("size") ?? 0
            freed_space += email_size
            this.inbox.remove(at: 0)
        }
    }
}

import std.collection.ArrayList

class EncryptionUtils {
    let key: String

    public init(key: String) {
        this.key = key
    }

    public func caesar_cipher(plaintext: String, shift: Int64): String {
        var ciphertext = ""
        let runes = plaintext.toRuneArray()
        for r in runes {
            if (r >= r'A' && r <= r'Z') {
                let ascii_offset: Int64 = 65
                let shifted = ((Int64(r) - ascii_offset + shift) % 26 + ascii_offset) as Rune
                ciphertext = ciphertext + String(from: shifted)
            } else if (r >= r'a' && r <= r'z') {
                let ascii_offset: Int64 = 97
                let shifted = ((Int64(r) - ascii_offset + shift) % 26 + ascii_offset) as Rune
                ciphertext = ciphertext + String(from: shifted)
            } else {
                ciphertext = ciphertext + String(from: r)
            }
        }
        return ciphertext
    }

    public func vigenere_cipher(plain_text: String): String {
        var encrypted_text = ""
        var key_index: Int64 = 0
        let key_runes = this.key.toRuneArray()
        let plain_runes = plain_text.toRuneArray()

        for r in plain_runes {
            if (r >= r'A' && r <= r'Z') || (r >= r'a' && r <= r'z') {
                let key_rune = key_runes[(key_index % Int64(key_runes.size)) as Int64].lower()
                let shift = Int64(key_rune) - Int64(r'a')

                var char_to_encrypt = r.lower()
                let encrypted_char_code = 
                    ((Int64(char_to_encrypt) - Int64(r'a') + shift) % 26 + Int64(r'a')) as Rune
                let encrypted_char = if (r >= r'A' && r <= r'Z') {
                    encrypted_char_code.upper()
                } else {
                    encrypted_char_code
                }
                encrypted_text = encrypted_text + String(from: encrypted_char)
                key_index += 1
            } else {
                encrypted_text = encrypted_text + String(from: r)
            }
        }
        return encrypted_text
    }

    public func rail_fence_cipher(plain_text: String, rails: Int64): String {
        // Create a 2D array representing the fence
        let plain_runes = plain_text.toRuneArray()
        var fence = ArrayList<ArrayList<Rune>>()
        for _ in 0..rails {
            var row = ArrayList<Rune>()
            for _ in 0..Int64(plain_runes.size) {
                row.add(r'\n')
            }
            fence.add(row)
        }

        var direction: Int64 = -1
        var row: Int64 = 0
        var col: Int64 = 0

        for r in plain_runes {
            if (row == 0 || row == rails - 1) {
                direction = -direction
            }

            fence[row as Int64][col as Int64] = r
            col += 1
            row += direction
        }

        var encrypted_text = ""
        for i in 0..rails {
            for j in 0..Int64(plain_runes.size) {
                if (fence[i as Int64][j as Int64] != r'\n') {
                    encrypted_text = encrypted_text + String(from: fence[i as Int64][j as Int64])
                }
            }
        }

        return encrypted_text
    }
}

// Helper extension methods (assuming we can add these)
func Rune.lower(): Rune {
    if (this >= r'A' && this <= r'Z') {
        return (Int64(this) + 32) as Rune
    }
    return this
}

func Rune.upper(): Rune {
    if (this >= r'a' && this <= r'z') {
        return (Int64(this) - 32) as Rune
    }
    return this
}

import std.math.numeric.Decimal
import std.regex.Regex
import std.collection.ArrayList
import std.collection.HashMap
import std.io.*

class ExpressionCalculator {

    let postfix_stack: ArrayList<String>
    let operat_priority: ArrayList<Int64>

    public init() {
        postfix_stack = ArrayList<String>()
        operat_priority = ArrayList<Int64>([0, 3, 2, 1, -1, 1, 0, 2])
    }

    public func calculate(expression: String): Float64 {
        let transformed = transform(expression)
        prepare(transformed)

        postfix_stack.reverse()
        let result_stack = ArrayList<Decimal>()

        while (postfix_stack.size > 0) {
            let current_op = postfix_stack.remove(at: 0)
            if (!is_operator(current_op)) {
                let num = if (current_op[0] == r'~') {
                    "${"-"}${current_op.substring(1)}"
                } else {
                    current_op
                }
                result_stack.add(Decimal(num))
            } else {
                let second_value = result_stack.remove(at: 0)
                let first_value = result_stack.remove(at: 0)
                let temp_result = _calculate(first_value, second_value, current_op)
                result_stack.add(temp_result)
            }
        }

        // Handle final multiplication (should only be one element in valid expressions)
        if (result_stack.size != 1) {
            throw RuntimeException("Invalid expression")
        }
        return result_stack[0].toFloat64()
    }

    public func prepare(expression: String): Unit {
        var op_stack = ArrayList<String>()
        op_stack.add(",")
        let arr = transform(expression)
        var current_index = 0
        var count = 0

        let chars = arr.toRuneArray()
        for (i in 0..chars.size) {
            let current_op = if (i < chars.size) { String(chars[i]) } else { "" }
            if (is_operator(current_op)) {
                if (count > 0) {
                    let substring = arr.substring(current_index, current_index + count)
                    postfix_stack.add(substring)
                }
                let peek_op = if (op_stack.size > 0) { op_stack[op_stack.size - 1] } else { "" }
                if (current_op == ")") {
                    while (op_stack[op_stack.size - 1] != "(") {
                        postfix_stack.add(op_stack.remove(at: op_stack.size - 1))
                    }
                    op_stack.remove(at: op_stack.size - 1)
                } else {
                    while (current_op != "(" && peek_op != "," && compare(current_op, peek_op)) {
                        postfix_stack.add(op_stack.remove(at: op_stack.size - 1))
                        let new_peek_op = if (op_stack.size > 0) { op_stack[op_stack.size - 1] } else { "" }
                    }
                    op_stack.add(current_op)
                }

                count = 0
                current_index = i + 1
            } else {
                count += 1
            }
        }

        if (count > 1 || (count == 1 && !is_operator(if (current_index < arr.size) { String(arr[current_index]) } else { "" }))) {
            postfix_stack.add(arr.substring(current_index, current_index + count))
        }

        while (op_stack[op_stack.size - 1] != ",") {
            postfix_stack.add(op_stack.remove(at: op_stack.size - 1))
        }
    }

    public static func is_operator(c: String): Bool {
        let operators = HashMap<String, Bool>([
            ("+", true),
            ("-", true),
            ("*", true),
            ("/", true),
            ("%", true),
            ("(", true),
            (")", true)
        ])
        return operators.contains(c) || operators.contains(c[0])
    }

    public func compare(cur: String, peek: String): Bool {
        var adjusted_cur = cur
        var adjusted_peek = peek
        if (cur == "%") {
            adjusted_cur = "/"
        }
        if (peek == "%") {
            adjusted_peek = "/"
        }

        let cur_code = peek[0].toASCII() - 40
        let peek_code = adjusted_peek[0].toASCII() - 40
        if (cur_code < 0 || cur_code >= operat_priority.size || peek_code < 0 || peek_code >= operat_priority.size) {
            return false
        }
        return operat_priority[peek_code] >= operat_priority[cur_code]
    }

    public static func _calculate(first_value: Decimal, second_value: Decimal, current_op: String): Decimal {
        match (current_op) {
            case "+" => return first_value + second_value
            case "-" => return first_value - second_value
            case "*" => return first_value * second_value
            case "/" => return first_value / second_value
            case "%" => return first_value % second_value
            case _ => throw RuntimeException("Unexpected operator: ${current_op}")
        }
    }

    public static func transform(expression: String): String {
        let re1 = Regex("\\s+")
        let re2 = Regex("=$")
        var expr = re1.replace(expression, "")
        expr = re2.replace(expr, "")
        let runes = expr.toRuneArray()
        var arr = ArrayList<Rune>()
        for (r in runes) {
            arr.add(r)
        }

        for (i in 0..arr.size) {
            if (i < arr.size && arr[i] == r'-') {
                if (i == 0) {
                    arr[i] = r'~'
                } else {
                    let prev_c = if (i > 0) { arr[i - 1] } else { r' ' }
                    let prev_str = String(prev_c)
                    if (is_operator(String(prev_c)) || prev_str == "E" || prev_str == "e") {
                        arr[i] = r'~'
                    }
                }
            }
        }

        let final_arr = runes
        if (final_arr.size > 1 && final_arr[0] == r'~' && final_arr[1] == r'(') {
            final_arr[0] = r'-'
            let prefix = Rune(r'0')
            let new_arr = ArrayList<Rune>([prefix])
            for (r in final_arr) {
                new_arr.add(r)
            }
            return String(new_arr.toRuneArray())
        }
        return String(final_arr)
    }
}

import std.collection.ArrayList
import std.collection.HashMap

class FitnessTracker {
    let height: Float64
    let weight: Float64
    let age: Int64
    let sex: String
    let BMI_std: ArrayList<HashMap<String, ArrayList<Int64>>>

    public init(height: Float64, weight: Float64, age: Int64, sex: String) {
        this.height = height
        this.weight = weight
        this.age = age
        this.sex = sex
        this.BMI_std = ArrayList<HashMap<String, ArrayList<Int64>>>()
        let male_map = HashMap<String, ArrayList<Int64>>()
        male_map.add("male", ArrayList<Int64>([20, 25]))
        let female_map = HashMap<String, ArrayList<Int64>>()
        female_map.add("female", ArrayList<Int64>([19, 24]))
        this.BMI_std.add(male_map)
        this.BMI_std.add(female_map)
    }

    public func get_BMI(): Float64 {
        return weight / (height * height)
    }

    public func condition_judge(): Int64 {
        let BMI = get_BMI()
        let sex_map = if (sex == "male") {
            BMI_std[0]
        } else {
            BMI_std[1]
        }! // Force unwrap since we're accessing valid indices
        let range = if (sex == "male") {
            sex_map.get("male")!
        } else {
            sex_map.get("female")!
        }!
        if (BMI > range[1]) {
            return 1
        } else if (BMI < range[0]) {
            return -1
        } else {
            return 0
        }
    }

    public func calculate_calorie_intake(): Float64 {
        let sex_float64 = if (sex == "male") { 1.0 } else { -1.0 }
        let BMR: Float64 = 
            if (sex == "male") {
                10.0 * weight + 6.25 * height - 5.0 * Float64(age) + 5.0
            } else {
                10.0 * weight + 6.25 * height - 5.0 * Float64(age) - 161.0
            }
        let condition = condition_judge()
        let multiplier: Float64 = 
            if (condition == 1) { 1.2 }
            else if (condition == -1) { 1.6 }
            else { 1.4 }
        return BMR * multiplier
    }
}

import std.collection.ArrayList

class GomokuGame {
    let board_size: Int64
    let board: ArrayList<ArrayList<String>>
    var current_player: String

    public init(board_size: Int64) {
        this.board_size = board_size
        this.board = ArrayList<ArrayList<String>>()
        this.current_player = "X"
        for (_ in 0..board_size) {
            let row: ArrayList<String> = ArrayList<String>()
            for (_ in 0..board_size) {
                row.add(" ")
            }
            board.add(row)
        }
    }

    public func make_move(row: Int64, col: Int64): Bool {
        if (board[row][col] == " ") {
            board[row][col] = current_player
            current_player = if (current_player == "X") { "O" } else { "X" }
            return true
        }
        return false
    }

    public func check_winner(): Option<String> {
        let directions: ArrayList<(Int64, Int64)> = ArrayList<(Int64, Int64)>([(0, 1), (1, 0), (1, 1), (1, -1)])
        for (row in 0..board_size) {
            for (col in 0..board_size) {
                if (board[row][col] != " ") {
                    for (dir in directions) {
                        if (this._check_five_in_a_row(row, col, (dir[0], dir[1]))) {
                            return Some<String>(board[row][col])
                        }
                    }
                }
            }
        }
        return None<String>
    }

    public func _check_five_in_a_row(row: Int64, col: Int64, direction: (Int64, Int64)): Bool {
        let (dx, dy) = direction
        var count: Int64 = 1
        let symbol = board[row][col]
        for (i in 1..5) {
            let new_row = row + dx * i
            let new_col = col + dy * i
            if (new_row < 0 || new_row >= board_size || new_col < 0 || new_col >= board_size) {
                return false
            }
            if (board[new_row][new_col] != symbol) {
                return false
            }
            count += 1
        }
        return count == 5
    }
}

import std.collection.HashMap

class Hotel {
    let name: String
    let available_rooms: HashMap<String, Int64>
    var booked_rooms: HashMap<String, HashMap<String, Int64>>

    public init(name: String, rooms: HashMap<String, Int64>) {
        this.name = name
        this.available_rooms = HashMap<String, Int64>(rooms)
        this.booked_rooms = HashMap<String, HashMap<String, Int64>>()
    }

    public func book_room(room_type: String, room_number: Int64, name: String): String {
        if (!this.available_rooms.contains(room_type)) {
            return "false"
        }

        let available = this.available_rooms[room_type] ?? 0
        if (room_number <= available) {
            if (!this.booked_rooms.contains(room_type)) {
                this.booked_rooms[room_type] = HashMap<String, Int64>()
            }
            let booked = this.booked_rooms[room_type] ?? HashMap<String, Int64>()
            let existing = booked[name] ?? 0
            this.booked_rooms[room_type]![name] = existing + room_number
            this.available_rooms[room_type] = available - room_number
            return "Success!"
        } else if (available != 0) {
            return available.toString()
        } else {
            return "false"
        }
    }

    public func check_in(room_type: String, room_number: Int64, name: String): Bool {
        if (!this.booked_rooms.contains(room_type)) {
            return false
        }

        let booked = this.booked_rooms[room_type] ?? HashMap<String, Int64>()
        if (!booked.contains(name)) {
            return false
        }

        let total_booked = booked[name] ?? 0
        if (room_number > total_booked) {
            return false
        }

        if (room_number == total_booked) {
            this.booked_rooms[room_type]!.remove(name)
        } else {
            this.booked_rooms[room_type]![name] = total_booked - room_number
        }
        return true
    }

    public func check_out(room_type: String, room_number: Int64): Unit {
        if (this.available_rooms.contains(room_type)) {
            let current = this.available_rooms[room_type] ?? 0
            this.available_rooms[room_type] = current + room_number
        } else {
            this.available_rooms[room_type] = room_number
        }
    }

    public func get_available_rooms(room_type: String): Int64 {
        return this.available_rooms[room_type] ?? 0
    }
}

