class HRManagementSystem {
    var employees: HashMap<Int64, Employee>

    public init() {
        this.employees = HashMap<Int64, Employee>()
    }

    public func add_employee(employee_id: Int64, name: String, position: String, 
                           department: String, salary: Int64): Bool {
        if (this.employees.get(employee_id) != None) {
            return false
        } else {
            this.employees.add(employee_id, Employee(name, position, department, salary))
            return true
        }
    }

