        let opt = this.employees.get(employee_id)
        if (opt == None) {
            return false
        }
        let emp = opt.getOrThrow()

        let name_opt = employee_info.get("name")
        let pos_opt = employee_info.get("position")
        let dept_opt = employee_info.get("department")
        let salary_opt = employee_info.get("salary")

        if (name_opt is None || pos_opt is None || dept_opt is None || salary_opt is None) {
