        for (id, emp) in this.employees {
            result.add(emp)
        }
        return result
    }
}

import std.collection.ArrayList

class Interpolation {
    public static func interpolate_1d(x: ArrayList<Float64>, y: ArrayList<Float64>, x_interp: ArrayList<Float64>): ArrayList<Float64> {
        let y_interp = ArrayList<Float64>()
        for (xi) in x_interp {
            var found = false
            for (i in 0..x.size-1) {
                let x_i = x[i]
                let x_i1 = x[i+1]
                if (x_i <= xi && xi <= x_i1) {
                    let y_i = y[i]
                    let y_i1 = y[i+1]
                    let yi = y_i + (y_i1 - y_i) * (xi - x_i) / (x_i1 - x_i)
                    y_interp.add(yi)
                    found = true
                    break
                }
            }
            if (!found) {
                throw "Interpolation point out of bounds"
            }
        }
        return y_interp
    }

    public static func interpolate_2d(x: ArrayList<Float64>, y: ArrayList<Float64>, z: ArrayList<ArrayList<Float64>>, x_interp: ArrayList<Float64>, y_interp: ArrayList<Float64>): ArrayList<Float64> {
        let z_interp = ArrayList<Float64>()
        for (i in 0..x_interp.size-1) {
            let xi = x_interp[i]
            let yi = y_interp[i]
            var found = false
            for (ii in 0..x.size-1) {
                let x_i = x[ii]
                let x_i1 = x[ii+1]
                if (x_i <= xi && xi <= x_i1) {
                    for (jj in 0..y.size-1) {
                        let y_j = y[jj]
                        let y_j1 = y[jj+1]
                        if (y_j <= yi && yi <= y_j1) {
                            let z00 = z[ii][jj]
                            let z01 = z[ii][jj+1]
                            let z10 = z[ii+1][jj]
                            let z11 = z[ii+1][jj+1]
                            let numerator = z00 * (x_i1 - xi) * (y_j1 - yi) +
                                            z10 * (xi - x_i) * (y_j1 - yi) +
                                            z01 * (x_i1 - xi) * (yi - y_j) +
                                            z11 * (xi - x_i) * (yi - y_j)
                            let denominator = (x_i1 - x_i) * (y_j1 - y_j)
                            let zi = numerator / denominator
                            z_interp.add(zi)
                            found = true
                            break
                        }
                    }
                }
                if (found) {
                    break
                }
            }
            if (!found) {
                throw "Interpolation point out of bounds"
            }
        }
        return z_interp
    }
}

import std.convert.Parsable
import std.convert.Formattable
import std.collection.ArrayList

class IPAddress {
    let ip_address: String

    public init(ip_address: String) {
        this.ip_address = ip_address
    }

    public func is_valid(): Bool {
        let octets = ip_address.split('.')
        if (octets.size != 4) {
            return false
        }
        for (let i = 0; i < 4; i = i + 1) {
            let octet = octets[i]
            if (!octet.isParsable<Int64>()) {
                return false
            }
            let num = octet.parse<Int64>() ?? 0 // fallback won't happen due to prior check
            if (num < 0 || num > 255) {
                return false
            }
        }
        return true
    }

    public func get_octets(): ArrayList<String> {
        if (!this.is_valid()) {
            return ArrayList<String>()
        }
        let result = ArrayList<String>()
        let octets = ip_address.split('.')
        for (let i = 0; i < 4; i = i + 1) {
            result.add(octets[i])
        }
        return result
    }

    public func get_binary(): String {
        if (!this.is_valid()) {
            return ""
        }
        let octets = ip_address.split('.')
        let binary_octets = ArrayList<String>()
        for (let i = 0; i < 4; i = i + 1) {
            let num = octets[i].parse<Int64>() ?? 0
            let binary_str = format<Int64>(num, "08b")
            binary_octets.add(binary_str)
        }
        return binary_octets.join('.')
    }
}

import std.net.IPAddress
import std.posix.gethostname

class IpUtil {
    /*
    This is a class as tool for ip that can be used to obtain the local IP address, validate its validity, and also provides the functionality to retrieve the corresponding hostname.
    */

    public static func is_valid_ipv4(ip_address: String): Bool {
        /*
        Check if the given IP address is a valid IPv4 address.
        :param ip_address: String, the IP address to check
        :return: Bool, true if the IP address is valid, false otherwise
        >>> IpUtil.is_valid_ipv4('192.168.0.123')
        true
        >>> IpUtil.is_valid_ipv4('256.0.0.0')
        false
        */
        let result = IPAddress.parse(ip_address)
        match (result) {
            case Some(ip) => return ip.isIPv4()
            case None => return false
        }
    }

    public static func is_valid_ipv6(ip_address: String): Bool {
        /*
        Check if the given IP address is a valid IPv6 address.
        :param ip_address:String, the IP address to check
        :return:Bool, true if the IP address is valid, false otherwise
        >>> IpUtil.is_valid_ipv6('2001:0db8:85a3:0000:0000:8a2e:0370:7334')
        true
        >>> IpUtil.is_valid_ipv6('2001:0db8:85a3:::8a2e:0370:7334')
        false
        */
        let result = IPAddress.parse(ip_address)
        match (result) {
            case Some(ip) => return ip.isIPv6()
            case None => return false
        }
    }

    public static func get_hostname(ip_address: String): Option<String> {
        /*
        Get the hostname associated with the given IP address.
        :param ip_address:String, the IP address to get the hostname for
        :return: String, the hostname associated with the IP address
        >>> IpUtil.get_hostname('110.242.68.3')
        'www.baidu.com'
        >>> IpUtil.get_hostname('10.0.0.1')
        None
        */
        let result = gethostname.reverseLookup(ip_address)
        return result
    }
}

