        this.jobListings = ArrayList<JobListing>()
        this.resumes = ArrayList<Resume>()
    }

    public func post_job(job_title: String, company: String, requirements: ArrayList<String>): Unit {
        let job = JobListing(job_title: job_title, company: company, requirements: requirements)
        this.jobListings.add(job)
    }

    public func remove_job(job: JobListing): Unit {
        this.jobListings.remove(job)
    }

    public func submit_resume(name: String, skills: ArrayList<String>, experience: String): Unit {
        let resume = Resume(name: name, skills: skills, experience: experience)
        this.resumes.add(resume)
    }

    public func withdraw_resume(resume: Resume): Unit {
        this.resumes.remove(resume)
    }

    public func search_jobs(criteria: String): ArrayList<JobListing> {
        let matchingJobs = ArrayList<JobListing>()
        for jobListing in this.jobListings {
            let lowerCriteria = criteria.lower()
            let titleMatch = jobListing.job_title.lower().contains(lowerCriteria)
            let reqMatch = this.contains_in_arraylist(list: jobListing.requirements, substr: lowerCriteria)
            if (titleMatch || reqMatch) {
                matchingJobs.add(jobListing)
            }
        }
        return matchingJobs
    }

    public func get_job_applicants(job: JobListing): ArrayList<Resume> {
        let applicants = ArrayList<Resume>()
        for resume in this.resumes {
            if (JobMarketplace.matches_requirements(resume: resume, requirements: job.requirements)) {
                applicants.add(resume)
            }
        }
        return applicants
    }

    public static func matches_requirements(resume: Resume, requirements: ArrayList<String>): Bool {
        for skill in resume.skills {
            let found = false
            for req in requirements {
                if (skill == req) {
                    found = true
                    break
                }
            }
            if (!found) {
                return false
            }
        }
        return true
    }

    func contains_in_arraylist(list: ArrayList<String>, substr: String): Bool {
        for item in list {
            if (item.lower().contains(substr)) {
                return true
            }
        }
        return false
    }
}

import std.collection.ArrayList
import std.math.abs

class KappaCalculator {

    public static func kappa(testData: ArrayList<ArrayList<Int64>>, k: Int64): Float64 {
        var P0: Float64 = 0.0
        let sumRows = testData.size
        let sumCols = if (sumRows > 0) { testData[0].size } else { 0 }

        // Calculate P0 (diagonal elements sum / total sum)
        for (i in 0..k) {
            if (i < sumRows && i < sumCols) {
                P0 += Float64(testData[i][i])
            }
        }

        // Calculate xsum (row sums) and ysum (column sums)
        var xsum = ArrayList<Float64>([0.0; sumRows])
        var ysum = ArrayList<Float64>([0.0; sumCols])

        for (i in 0..sumRows) {
            for (j in 0..sumCols) {
                if (i < testData.size && j < testData[i].size) {
                    let val = Float64(testData[i][j])
                    xsum[i] += val
                    ysum[j] += val
                }
            }
        }

        // Calculate total sum
        var sum: Float64 = 0.0
        for (i in 0..sum) {
            if (i < xsum.size) {
                sum += xsum[i]
            }
        }

        // Calculate Pe
        var PeProduct: Float64 = 0.0
        for (j in 0..sumCols) {
            if (j < ysum.size) {
                PeProduct += ysum[j] * ysum[j]
            }
        }
        let Pe = PeProduct / (sum * sum)

        // Final calculation
        P0 /= sum
        if (1.0 - Pe == 0.0) {
            return 0.0 // Avoid division by zero (corner case)
        }
        return (P0 - Pe) / (1.0 - Pe)
    }

    public static func fleiss_kappa(testData: ArrayList<ArrayList<Int64>>, N: Int64, k: Int64, n: Int64): Float64 {
        var sumAll: Float64 = 0.0
        var P0: Float64 = 0.0
        let oneMat = ArrayList<ArrayList<Float64>>([ArrayList<Float64>([1.0; k])]) // 1xk matrix of 1s

        // Calculate P0 and total sum
        for (i in 0..N) {
            var temp: Float64 = 0.0
            var rowSum: Float64 = 0.0
            if (i < testData.size) {
                for (j in 0..k) {
                    if (j < testData[i].size) {
                        let val = Float64(testData[i][j])
                        sumAll += val
                        rowSum += val
                        temp += val * val
                    }
                }
            }
            temp -= Float64(n)
            temp /= (Float64(n) - 1.0) * Float64(n)
            P0 += temp
        }

        P0 /= Float64(N)

        // Calculate ysum (column sums)
        var ysum = ArrayList<Float64>([0.0; k])
        for (i in 0..testData.size) {
            for (j in 0..k) {
                if (i < testData.size && j < testData[i].size) {
                    ysum[j] += Float64(testData[i][j])
                }
            }
        }

        // Calculate Pe (sum of (ysum/sum)^2)
        var Pe: Float64 = 0.0
        for (j in 0..k) {
            if (j < ysum.size && sumAll != 0.0) {
                let term = (ysum[j] / sumAll) * (ysum[j] / sumAll)
                Pe += term
            }
        }

        // Final calculation
        if (1.0 - Pe == 0.0) {
            return 0.0 // Avoid division by zero (corner case)
        }
        return (P0 - Pe) / (1.0 - Pe)
    }
}

