class LongestWord {

    let word_list: ArrayList<String>

    public init() {
        this.word_list = ArrayList<String>()
    }

    public func add_word(word: String): Unit {
        this.word_list.add(word)
    }

    public func find_longest_word(sentence: String): String {
        var longest_word: String = ""
        let punctuation_regex = Regex(r"[%s]" % escape_string(get_punctuation()))
        let cleaned_sentence = punctuation_regex.replace(sentence, "")
        let words = cleaned_sentence.split(' ')
        for word in words {
            if this.word_list.contains(word) && word.size > longest_word.size {
                longest_word = word
            }
        }
        return longest_word
    }
}

