import std.collection.ArrayList
import std.collection.HashSet
import std.random.Random

class MahjongConnect {

    let BOARD_SIZE: ArrayList<Int64>
    let ICONS: ArrayList<String>
    var board: ArrayList<ArrayList<String>>

    public init(BOARD_SIZE: ArrayList<Int64>, ICONS: ArrayList<String>) {
        this.BOARD_SIZE = BOARD_SIZE
        this.ICONS = ICONS
        this.board = this.create_board(BOARD_SIZE, ICONS)
    }

    public static func create_board(BOARD_SIZE: ArrayList<Int64>, ICONS: ArrayList<String>): ArrayList<ArrayList<String>> {
        let rows = BOARD_SIZE[0]
        let cols = BOARD_SIZE[1]
        let random = Random()
        var board = ArrayList<ArrayList<String>>()

        for (i in 0..rows) {
            var row = ArrayList<String>()
            for (j in 0..cols) {
                let randomIndex = random.nextInt(ICONS.size)
                row.add(ICONS[randomIndex])
            }
            board.add(row)
        }
        return board
    }

    public func is_valid_move(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        let x1 = pos1[0]
        let y1 = pos1[1]
        let x2 = pos2[0]
        let y2 = pos2[1]

        // Check if positions are within the game board range
        if (!(0 <= x1 && x1 < BOARD_SIZE[0] && 0 <= y1 && y1 < BOARD_SIZE[1] && 
              0 <= x2 && x2 < BOARD_SIZE[0] && 0 <= y2 && y2 < BOARD_SIZE[1])) {
            return false
        }

        // Check if the two positions are the same
        if (pos1 == pos2) {
            return false
        }

        // Check if the two positions have the same icon
        if (this.board[x1][y1] != this.board[x2][y2]) {
            return false
        }

        // Check if there is a valid path between the two positions
        if (!this.has_path(pos1, pos2)) {
            return false
        }

        return true
    }

    public func has_path(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        let x1 = pos1[0]
        let y1 = pos1[1]
        let x2 = pos2[0]
        let y2 = pos2[1]

        var visited = ArrayList<(Int64, Int64)>()
        var stack = ArrayList<(Int64, Int64)>()
        stack.add(pos1)

        while (!stack.isEmpty()) {
            let current_pos = stack.remove(at: stack.size - 1)
            let current_x = current_pos[0]
            let current_y = current_pos[1]

            if (current_x == x2 && current_y == y2) {
                return true
            }

            if (this.contains(visited: visited, pos: current_pos)) {
                continue
            }

            visited.add(current_pos)

            // Directions: up, down, left, right
            let directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
            for (dir in directions) {
                let dx = dir[0]
                let dy = dir[1]
                let new_x = current_x + dx
                let new_y = current_y + dy

                if (0 <= new_x && new_x < BOARD_SIZE[0] && 0 <= new_y && new_y < BOARD_SIZE[1]) {
                    if (!this.contains(visited: visited, pos: (new_x, new_y)) && 
                        this.board[new_x][new_y] == this.board[x1][y1]) {
                        stack.add((new_x, new_y))
                    }
                }
            }
        }
        return false
    }

    public static func contains(visited: ArrayList<(Int64, Int64)>, pos: (Int64, Int64)): Bool {
        for (v in visited) {
            if (v == pos) {
                return true
            }
        }
        return false
    }

    public func remove_icons(pos1: (Int64, Int64), pos2: (Int64, Int64)): Unit {
        let x1 = pos1[0]
        let y1 = pos1[1]
        let x2 = pos2[0]
        let y2 = pos2[1]

        this.board[x1][y1] = " "
        this.board[x2][y2] = " "
    }

    public func is_game_over(): Bool {
        for (row in this.board) {
            for (cell in row) {
                if (cell != " ") {
                    return false
                }
            }
        }
        return true
    }
}

import std.collection.*

class Manacher {
    let input_string: String

    public init(input_string: String) {
        this.input_string = input_string
    }

    public func palindromic_length(center: Int64, diff: Int64, string: String): Int64 {
        let len = string.size.toI64()
        if (center - diff == -1 || center + diff == len || 
            string[center - diff] != string[center + diff]) {
            return 0
        }
        return 1 + this.palindromic_length(center: center, diff: diff + 1, string: string)
    }

    public func palindromic_string(): String {
        var max_length: Int64 = 0
        var start: Int64 = 0

        var new_input_string = ""
        for (i in 0..<this.input_string.size) {
            if (i < this.input_string.size - 1) {
                new_input_string += this.input_string[i] + "|"
            } else {
                new_input_string += this.input_string[i]
            }
        }

        for (i in 0..<new_input_string.size.toI64()) {
            let length = this.palindromic_length(center: i, diff: 1, string: new_input_string)
            if (max_length < length) {
                max_length = length
                start = i - max_length
            }
        }

        var output_string = ""
        for (i in start..<start + 2 * max_length + 1) {
            if (i >= 0 && i < new_input_string.size && new_input_string[i] != '|') {
                output_string += new_input_string[i]
            }
        }

        return output_string
    }
}

import std.collection.ArrayList
import std.math.abs

class MetricsCalculator {

    var true_positives: Int64
    var false_positives: Int64
    var false_negatives: Int64
    var true_negatives: Int64

    public init() {
        this.true_positives = 0
        this.false_positives = 0
        this.false_negatives = 0
        this.true_negatives = 0
    }

    public func update(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Unit {
        for (i in 0..predicted_labels.size) {
            let predicted = predicted_labels[i]
            let true = true_labels[i]
            if (predicted == 1 && true == 1) {
                this.true_positives += 1
            } else if (predicted == 1 && true == 0) {
                this.false_positives += 1
            } else if (predicted == 0 && true == 1) {
                this.false_negatives += 1
            } else if (predicted == 0 && true == 0) {
                this.true_negatives += 1
            }
        }
    }

    public func precision(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        this.update(predicted_labels, true_labels)
        let denominator = this.true_positives + this.false_positives
        if (denominator == 0) {
            return 0.0
        }
        return Float64(this.true_positives) / Float64(denominator)
    }

    public func recall(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        this.update(predicted_labels, true_labels)
        let denominator = this.true_positives + this.false_negatives
        if (denominator == 0) {
            return 0.0
        }
        return Float64(this.true_positives) / Float64(denominator)
    }

    public func f1_score(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        this.update(predicted_labels, true_labels)
        let precision = this.precision(predicted_labels, true_labels)
        let recall = this.recall(predicted_labels, true_labels)
        if (precision + recall == 0.0) {
            return 0.0
        }
        return (2.0 * precision * recall) / (precision + recall)
    }

    public func accuracy(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        this.update(predicted_labels, true_labels)
        let total = this.true_positives + this.true_negatives + this.false_positives + this.false_negatives
        if (total == 0) {
            return 0.0
        }
        return Float64(this.true_positives + this.true_negatives) / Float64(total)
    }
}

import std.collection.ArrayList
