class MetricsCalculator2 {

    public init() {}

    public static func mrr(data: Any): (Float64, ArrayList<Float64>) {
        match (data) {
            case is Tuple && d: (ArrayList<Int64>, Int64) => {
                let (sub_list, total_num) = d as! (ArrayList<Int64>, Int64)
                if (total_num == 0 || sub_list.size == 0) {
                    return (0.0, ArrayList<Float64>([0.0]))
                }

                var ranking_array = ArrayList<Float64>()
                for (i in 0..sub_list.size) {
                    ranking_array.add(1.0 / (i + 1))
                }

                var mr_np = ArrayList<Float64>()
                for (i in 0..sub_list.size) {
                    mr_np.add(sub_list[i] * ranking_array[i])
                }

                var mr: Float64 = 0.0
                for (i in 0..mr_np.size) {
                    if (mr_np[i] > 0) {
                        mr = mr_np[i]
                        break
                    }
                }

                return (mr, ArrayList<Float64>([mr]))
            }
            case is ArrayList && d: ArrayList<Tuple> => {
                if (d.size == 0) {
                    return (0.0, ArrayList<Float64>([0.0]))
                }

                var separate_result = ArrayList<Float64>()
                for (i in 0..d.size) {
                    let (sub_list, total_num) = d[i] as! (ArrayList<Int64>, Int64)

                    if (total_num == 0 || sub_list.size == 0) {
                        separate_result.add(0.0)
                        continue
                    }

                    var ranking_array = ArrayList<Float64>()
                    for (j in 0..sub_list.size) {
                        ranking_array.add(1.0 / (j + 1))
                    }

                    var mr_np = ArrayList<Float64>()
                    for (j in 0..sub_list.size) {
                        mr_np.add(sub_list[j] * ranking_array[j])
                    }

                    var mr: Float64 = 0.0
                    for (j in 0..mr_np.size) {
                        if (mr_np[j] > 0) {
                            mr = mr_np[j]
                            break
                        }
                    }

                    separate_result.add(mr)
                }

                // Calculate mean
                var sum = 0.0
                for (value in separate_result) {
                    sum += value
                }
                let mean = sum / separate_result.size

                return (mean, separate_result)
            }
            case _ => {
                throw Exception("the input must be a tuple of (ArrayList<Int64>, Int64) or a list of such tuples")
            }
        }
    }

    public static func map(data: Any): (Float64, ArrayList<Float64>) {
        match (data) {
            case is Tuple && d: (ArrayList<Int64>, Int64) => {
                let (sub_list, total_num) = d as! (ArrayList<Int64>, Int64)
                if (total_num == 0 || sub_list.size == 0) {
                    return (0.0, ArrayList<Float64>([0.0]))
                }

                var ranking_array = ArrayList<Float64>()
                for (i in 0..sub_list.size) {
                    ranking_array.add(1.0 / (i + 1))
                }

                var right_ranking_list = ArrayList<Int64>()
                var count = 1
                for (t in sub_list) {
                    if (t == 0) {
                        right_ranking_list.add(0)
                    } else {
                        right_ranking_list.add(count)
                        count += 1
                    }
                }

                var ap_numerator = 0.0
                for (i in 0..right_ranking_list.size) {
                    ap_numerator += right_ranking_list[i] * ranking_array[i]
                }

                let ap = ap_numerator / total_num
                return (ap, ArrayList<Float64>([ap]))
            }
            case is ArrayList && d: ArrayList<Tuple> => {
                if (d.size == 0) {
                    return (0.0, ArrayList<Float64>([0.0]))
                }

                var separate_result = ArrayList<Float64>()
                for (i in 0..d.size) {
                    let (sub_list, total_num) = d[i] as! (ArrayList<Int64>, Int64)

                    if (total_num == 0 || sub_list.size == 0) {
                        separate_result.add(0.0)
                        continue
                    }

                    var ranking_array = ArrayList<Float64>()
                    for (j in 0..sub_list.size) {
                        ranking_array.add(1.0 / (j + 1))
                    }

                    var right_ranking_list = ArrayList<Int64>()
                    var count = 1
                    for (t in sub_list) {
                        if (t == 0) {
                            right_ranking_list.add(0)
                        } else {
                            right_ranking_list.add(count)
                            count += 1
                        }
                    }

                    var ap_numerator = 0.0
                    for (j in 0..right_ranking_list.size) {
                        ap_numerator += right_ranking_list[j] * ranking_array[j]
                    }

                    let ap = ap_numerator / total_num
                    separate_result.add(ap)
                }

                // Calculate mean
                var sum = 0.0
                for (value in separate_result) {
                    sum += value
                }
                let mean = sum / separate_result.size

                return (mean, separate_result)
            }
            case _ => {
                throw Exception("the input must be a tuple of (ArrayList<Int64>, Int64) or a list of such tuples")
            }
        }
    }
}

import std.collection.ArrayList
import std.random.Random
import std.convert.Parsable

class MinesweeperGame {

    let n: Int64
    let k: Int64
    var minesweeper_map: ArrayList<ArrayList<String>>
    var player_map: ArrayList<ArrayList<String>>
    var score: Int64
    var rand = Random()

    public init(n: Int64, k: Int64) {
        this.n = n
        this.k = k
        this.minesweeper_map = this.generate_mine_sweeper_map(n, k)
        this.player_map = this.generate_playerMap(n)
        this.score = 0
    }

    public func generate_mine_sweeper_map(n: Int64, k: Int64): ArrayList<ArrayList<String>> {
        let map = ArrayList<ArrayList<String>>()

        // Initialize empty grid
        for _ in 0..n {
            let row = ArrayList<String>()
            for _ in 0..n {
                row.add("0")
            }
            map.add(row)
        }

        // Place mines and update counts
        var mines_placed = 0
        while (mines_placed < k) {
            let x = this.rand.nextInt(n)
            let y = this.rand.nextInt(n)

            if (map[y][x] != "X") {
                map[y][x] = "X"
                mines_placed += 1

                // Update adjacent cells
                for dy in -1..2 {
                    for dx in -1..2 {
                        if (dx == 0 && dy == 0) {
                            continue
                        }
                        let ny = y + dy
                        let nx = x + dx
                        if (ny >= 0 && ny < n && nx >= 0 && nx < n && map[ny][nx] != "X") {
                            if (map[ny][nx] == "0") {
                                map[ny][nx] = "1"
                            } else {
                                let current = map[ny][nx].toInt64() ?? 0
                                map[ny][nx] = (current + 1).toString()
                            }
                        }
                    }
                }
            }
        }
        return map
    }

    public func generate_playerMap(n: Int64): ArrayList<ArrayList<String>> {
        let map = ArrayList<ArrayList<String>>()
        for _ in 0..n {
            let row = ArrayList<String>()
            for _ in 0..n {
                row.add("-")
            }
            map.add(row)
        }
        return map
    }

    public func check_won(map: ArrayList<ArrayList<String>>): Bool {
        for y in 0..this.n {
            for x in 0..this.n {
                if (map[y][x] == "-" && this.minesweeper_map[y][x] != "X") {
                    return false
                }
            }
        }
        return true
    }

    public func sweep(x: Int64, y: Int64): Any {
        if (x < 0 || x >= this.n || y < 0 || y >= this.n) {
            return this.player_map
        }

        if (this.minesweeper_map[y][x] == "X") {
            return false
        }

        this.player_map[y][x] = this.minesweeper_map[y][x]
        this.score += 1

        if (this.check_won(this.player_map)) {
            return true
        }

        return this.player_map
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.time.DateTime
import std.time.format

class MovieBookingSystem {
    let movies: ArrayList<HashMap<String, Any>>

    public init() {
        movies = ArrayList<HashMap<String, Any>>()
    }

    public func add_movie(name: String, price: Float64, start_time: String, end_time: String, n: Int64): Unit {
        let seatMatrix = ArrayList<ArrayList<Int64>>()
        for (i in 0..n) {
            let row = ArrayList<Int64>()
            for (j in 0..n) {
                row.add(0)
            }
            seatMatrix.add(row)
        }

        let movie = HashMap<String, Any>([
            ("name", name),
            ("price", price),
            ("start_time", DateTime.parse(start_time, format: "yyyy/MM/dd HH:mm")),
            ("end_time", DateTime.parse(end_time, format: "yyyy/MM/dd HH:mm")),
            ("seats", seatMatrix)
        ])
        movies.add(movie)
    }

    public func book_ticket(name: String, seats_to_book: ArrayList<ArrayList<Int64>>): String {
        for (movie in movies) {
            let movieName = movie.get("name") as String
            if (movieName == name) {
                let seats = movie.get("seats") as ArrayList<ArrayList<Int64>>
                for (seat in seats_to_book) {
                    let row = seat[0] as Int64
                    let col = seat[1] as Int64
                    if (seats[row][col] == 1) {
                        return "Booking failed."
                    }
                }
                for (seat in seats_to_book) {
                    let row = seat[0] as Int64
                    let col = seat[1] as Int64
                    seats[row][col] = 1
                }
                return "Booking success."
            }
        }
        return "Movie not found."
    }

    public func available_movies(start_time: String, end_time: String): ArrayList<String> {
        let result = ArrayList<String>()
        let queryStart = DateTime.parse(start_time, format: "yyyy/MM/dd HH:mm")
        let queryEnd = DateTime.parse(end_time, format: "yyyy/MM/dd HH:mm")

        for (movie in movies) {
            let movieStart = movie.get("start_time") as DateTime
            let movieEnd = movie.get("end_time") as DateTime
            if (queryStart <= movieStart && movieEnd <= queryEnd) {
                result.add(movie.get("name") as String)
            }
        }
        return result
    }
}

import std.random.Random
import std.collection.ArrayList

class MusicPlayer {
    var playlist: ArrayList<String>
    var current_song: Option<String>
    var volume: Int64

    public init() {
        this.playlist = ArrayList<String>()
        this.current_song = None
        this.volume = 50
    }

    public func add_song(song: String): Unit {
        this.playlist.add(song)
    }

    public func remove_song(song: String): Unit {
        if (this.playlist.contains(song)) {
            this.playlist.remove(song)
            if (this.current_song.getOrThrow() == song) {
                this.stop()
            }
        }
    }

    public func play(): Option<String> {
        if (this.playlist.size == 0) {
            return None
        }
        return match (this.current_song) {
            case Some(s) => Some(s)
            case None() => 
                let first = this.playlist[0]
                this.current_song = Some(first)
                Some(first)
        }
    }

    public func stop(): Bool {
        return match (this.current_song) {
            case Some(_) => 
                this.current_song = None
                true
            case None() => false
        }
    }

    public func switch_song(): Bool {
        return match (this.current_song) {
            case Some(song) => 
                let index = -1
                for (i in 0..this.playlist.size) {
                    if (this.playlist[i] == song) {
                        index = i
                        break
                    }
                }
                if (index >= 0 && index < this.playlist.size - 1) {
                    this.current_song = Some(this.playlist[index + 1])
                    true
                } else {
                    false
                }
            case None() => false
        }
    }

    public func previous_song(): Bool {
        return match (this.current_song) {
            case Some(song) => 
                let index = -1
                for (i in 0..this.playlist.size) {
                    if (this.playlist[i] == song) {
                        index = i
                        break
                    }
                }
                if (index > 0) {
                    this.current_song = Some(this.playlist[index - 1])
                    true
                } else {
                    false
                }
            case None() => false
        }
    }

    public func set_volume(volume: Int64): Bool {
        if (volume >= 0 && volume <= 100) {
            this.volume = volume
            true
        } else {
            false
        }
    }

    public func shuffle(): Bool {
        if (this.playlist.size == 0) {
            return false
        }
        // Implement Fisher-Yates shuffle algorithm
        let random = Random()
        for (i in (this.playlist.size - 1)..0:-1) {
            let j = random.nextInt(i + 1)
            let temp = this.playlist[i]
            this.playlist[i] = this.playlist[j]
            this.playlist[j] = temp
        }
        return true
    }
}

