class NLPDataProcessor {

    public func construct_stop_word_list(): ArrayList<String> {
        let stop_word_list = ArrayList<String>()
        stop_word_list.add("a")
        stop_word_list.add("an")
        stop_word_list.add("the")
        return stop_word_list
    }

    public func remove_stop_words(string_list: ArrayList<String>, stop_word_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        let answer = ArrayList<ArrayList<String>>()

        for (i in 0..string_list.size) {
            let string = string_list[i]
            let string_split = string.split(" ")
            let filtered_words = ArrayList<String>()

            for (j in 0..string_split.size) {
                let word = string_split[j]
                var is_stop_word = false

                for (k in 0..stop_word_list.size) {
                    if (word == stop_word_list[k]) {
                        is_stop_word = true
                        break
                    }
                }

                if (!is_stop_word) {
                    filtered_words.add(word)
                }
            }

            answer.add(filtered_words)
        }

        return answer
    }

    public func process(string_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        let stop_word_list = this.construct_stop_word_list()
        return this.remove_stop_words(string_list, stop_word_list)
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.regex.Regex
import std.sort.sort
import std.unicode.UnicodeStringExtension

class NLPDataProcessor2 {

    public func process_data(string_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        var words_list = ArrayList<ArrayList<String>>()
        for (string in string_list) {
            // Remove non-English letters and convert to lowercase
            let pattern = Regex("[^a-zA-Z\\s]")
            let processed_string = pattern.replaceAll(string, "").toLowerCase()
            // Split the string into words
            let words = processed_string.split(" ")
            var word_array = ArrayList<String>(words)
            words_list.add(word_array)
        }
        return words_list
    }

    public func calculate_word_frequency(words_list: ArrayList<ArrayList<String>>): HashMap<String, Int64> {
        var word_frequency = HashMap<String, Int64>()
        for (words in words_list) {
            for (word in words) {
                if (word_frequency.containsKey(word)) {
                    var count = word_frequency[word] ?? 0
                    word_frequency[word] = count + 1
                } else {
                    word_frequency[word] = 1
                }
            }
        }

        // Convert HashMap to ArrayList of (word, count) pairs for sorting
        var entries = ArrayList<(String, Int64)>()
        for (entry in word_frequency.iterator()) {
            entries.add((entry.key, entry.value))
        }

        // Sort by frequency descending
        let key = {i: (String, Int64) => i[1]}
        sort(entries, key: key, descending: true)

        // Create new HashMap with top 5
        var top_5 = HashMap<String, Int64>()
        let limit = if (entries.size < 5) entries.size else 5
        for (i in 0..limit) {
            let entry = entries[i]
            top_5[entry[0]] = entry[1]
        }

        return top_5
    }

    public func process(string_list: ArrayList<String>): HashMap<String, Int64> {
        let words_list = self.process_data(string_list)
        let word_frequency_dict = self.calculate_word_frequency(words_list)
        return word_frequency_dict
    }
}

