class NumberWordFormatter {
    let NUMBER: Array<String>
    let NUMBER_TEEN: Array<String>
    let NUMBER_TEN: Array<String>
    let NUMBER_MORE: Array<String>
    let NUMBER_SUFFIX: Array<String>

    public init() {
        this.NUMBER = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        this.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                            "EIGHTEEN", "NINETEEN"]
        this.NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        this.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        this.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]
    }

    public func format(x: Option<String>): String {
        if (x.isSome()) {
            return this.format_string(x.getOrThrow())
        } else {
            return ""
        }
    }

    public func format_string(x: String): String {
        let parts = x.split('.')
        let lstr = parts[0]
        let rstr = if (parts.size > 1) { parts[1] } else { "" }

        var lstrrev = ""
        for (i in 0..<lstr.size) {
            lstrrev += lstr[lstr.size - 1 - i].toString()
        }

        var a = ArrayList<String>()
        for (i in 0..<5) {
            a.add("")
        }

        if (lstrrev.size % 3 == 1) {
            lstrrev += "00"
        } else if (lstrrev.size % 3 == 2) {
            lstrrev += "0"
        }

        var lm = ""
        for (i in 0..<(lstrrev.size / 3)) {
            let start = 3 * i
            let end = 3 * i + 3
            var segment = ""
            for (j in start..<end) {
                if (j < lstrrev.size) {
                    segment += lstrrev[j].toString()
                }
            }

            var reversed_segment = ""
            for (k in 0..<segment.size) {
                reversed_segment += segment[segment.size - 1 - k].toString()
            }

            a.set(i, reversed_segment)
            if (a[i] != "000") {
                lm = this.trans_three(a[i]) + " " + this.parse_more(i) + " " + lm
            } else {
                lm += this.trans_three(a[i])
            }
        }

        let xs = if (rstr.size > 0) { "AND CENTS " + this.trans_two(rstr) + " " } else { "" }
        let lm_stripped = lm.trim()
        if (lm_stripped == "") {
            return "ZERO ONLY"
        } else {
            return lm_stripped + " " + xs + "ONLY"
        }
    }

    public func trans_two(s: String): String {
        let padded = if (s.size < 2) { s.zfill(2) } else { s }
        if (padded[0] == '0') {
            return this.NUMBER[padded[1].toInt64() ?? 0]
        } else if (padded[0] == '1') {
            return this.NUMBER_TEEN[padded.toInt64() ?? 10 - 10]
        } else if (padded[1] == '0') {
            return this.NUMBER_TEN[padded[0].toInt64() ?? 0 - 1]
        } else {
            return this.NUMBER_TEN[padded[0].toInt64() ?? 0 - 1] + " " + this.NUMBER[padded[1].toInt64() ?? 0]
        }
    }

    public func trans_three(s: String): String {
        if (s.size == 0) {
            return ""
        } else if (s[0] == '0') {
            return this.trans_two(s.substring(1))
        } else if (s.substring(1) == "00") {
            return this.NUMBER[s[0].toInt64() ?? 0] + " HUNDRED"
        } else {
            return this.NUMBER[s[0].toInt64() ?? 0] + " HUNDRED AND " + this.trans_two(s.substring(1))
        }
    }

    public func parse_more(i: Int64): String {
        return this.NUMBER_MORE[i]
    }
}

import std.collection.ArrayList
import std.convert.RadixConvertible
import std.io.*

class NumericEntityUnescaper {

    public init() {}

    public func replace(string: String): String {
        let out = ArrayList<Rune>()
        var pos = 0
        let length = string.size()

        while (pos < length - 2) {
            if (string[pos] == r'&' && string[pos + 1] == r'#') {
                let start = pos + 2
                var is_hex = false
                let first_char = string[start]

                if (first_char == r'x' || first_char == r'X') {
                    is_hex = true
                    pos += 1  // Move past 'x'
                }

                if (start + (if (is_hex) 1 else 0) >= length) {
                    break
                }

                var end = start + (if (is_hex) 1 else 0)
                while (end < length && this.is_hex_char(string[end])) {
                    end += 1
                }

                if (end < length && string[end] == r';') {
                    let entity_str = string.substring(start, end)
                    let (ok, value) = if (is_hex) {
                        entity_str.toUInt64(radix: 16)
                    } else {
                        entity_str.toUInt64(radix: 10)
                    }

                    if (ok) {
                        out.add(Rune.fromCharCode(value))
                        pos = end + 1
                        continue
                    }
                }
            }

            out.add(string[pos])
            pos += 1
        }

        // Add remaining characters
        while (pos < length) {
            out.add(string[pos])
            pos += 1
        }

        return out.toString()
    }

    public static func is_hex_char(char: Rune): Bool {
        return char.isDigit() || (char >= r'a' && char <= r'f') || (char >= r'A' && char <= r'F')
    }
}

