func toStr(x: Int64): String {
    // Simplified int to string conversion - in practice, use proper library function
    // This is just a placeholder to make the code compile
    let digits = "0123456789"
    var num = x
    var is_negative = false

    if (num < 0) {
        is_negative = true
        num = -num
    }

    if (num == 0) {
        return "0"
    }

    var result = ""
    while (num > 0) {
        let digit = num % 10
        result = digits.runes()[digit..digit+1].toRuneArray().toStr() + result  // This is very inefficient
        num = num / 10
    }

    if (is_negative) {
        result = "-" + result
    }

    return result
}

