class PushBoxGame {
    let map: ArrayList<ArrayList<String>>
    var player_row: Int64
    var player_col: Int64
    let targets: ArrayList<ArrayList<Int64>>
    let boxes: ArrayList<ArrayList<Int64>>
    var target_count: Int64
    var is_game_over: Bool

    public init(map: ArrayList<ArrayList<String>>) {
        this.map = map
        this.player_row = 0
        this.player_col = 0
        this.targets = ArrayList<ArrayList<Int64>>()
        this.boxes = ArrayList<ArrayList<Int64>>()
        this.target_count = 0
        this.is_game_over = false

        func init_game() {
            for (i in 0..<map.size) {
                for (j in 0..<map[i].size) {
                    if (map[i][j] == "O") {
                        this.player_row = i
                        this.player_col = j
                    } else if (map[i][j] == "G") {
                        this.targets.add(ArrayList<Int64>([i, j]))
                        this.target_count += 1
                    } else if (map[i][j] == "X") {
                        this.boxes.add(ArrayList<Int64>([i, j]))
                    }
                }
            }
        }
        init_game()
    }

    public func check_win(): Bool {
        var box_on_target_count: Int64 = 0
        let target_set = HashSet<ArrayList<Int64>>()

        for target in this.targets {
            target_set.add(target)
        }

        for box in this.boxes {
            if (target_set.contains(box)) {
                box_on_target_count += 1
            }
        }

        if (box_on_target_count == this.target_count) {
            this.is_game_over = true
        }
        return this.is_game_over
    }

    public func move(direction: String): Bool {
        var new_player_row = this.player_row
        var new_player_col = this.player_col

        match (direction) {
            case "w" => new_player_row -= 1
            case "s" => new_player_row += 1
            case "a" => new_player_col -= 1
            case "d" => new_player_col += 1
            case _ => {} // do nothing for invalid direction
        }

        // Check if new position is valid (not wall)
        if (new_player_row >= 0 && new_player_row < this.map.size && 
            new_player_col >= 0 && new_player_col < this.map[0].size && 
            this.map[new_player_row][new_player_col] != "#") {

            // Check if there's a box in the new position
            var box_index: Int64 = -1
            var box_found = false
            for (i in 0..<this.boxes.size) {
                if (this.boxes[i][0] == new_player_row && this.boxes[i][1] == new_player_col) {
                    box_index = i
                    box_found = true
                    break
                }
            }

            if (box_found) {
                // Calculate new box position
                let new_box_row = new_player_row + (new_player_row - this.player_row)
                let new_box_col = new_player_col + (new_player_col - this.player_col)

                // Check if new box position is valid
                if (new_box_row >= 0 && new_box_row < this.map.size && 
                    new_box_col >= 0 && new_box_col < this.map[0].size && 
                    this.map[new_box_row][new_box_col] != "#") {

                    // Move box
                    this.boxes[box_index] = ArrayList<Int64>([new_box_row, new_box_col])
                    // Move player
                    this.player_row = new_player_row
                    this.player_col = new_player_col
                }
            } else {
                // Just move player
                this.player_row = new_player_row
                this.player_col = new_player_col
            }
        }

        return this.check_win()
    }
}

import std.regex.Regex
import std.collection.ArrayList

class RegexUtils {

    public func match_regex(pattern: String, text: String): Bool {
        let regex = Regex(pattern)
        return regex.matches(text)
    }

    public func findall(pattern: String, text: String): ArrayList<String> {
        let regex = Regex(pattern)
        let matches = regex.findAll(text)
        let result = ArrayList<String>()
        for (i, match) in matches.each() {
            result.add(match.group(0))
        }
        return result
    }

    public func split(pattern: String, text: String): ArrayList<String> {
        let regex = Regex(pattern)
        let parts = regex.split(text)
        let result = ArrayList<String>()
        for part in parts {
            result.add(part)
        }
        return result
    }

    public func sub(pattern: String, replacement: String, text: String): String {
        let regex = Regex(pattern)
        return regex.replace(text, replacement)
    }

    public func generate_email_pattern(): String {
        return r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b'
    }

    public func generate_phone_number_pattern(): String {
        return r'\b\d{3}-\d{3}-\d{4}\b'
    }

    public func generate_split_sentences_pattern(): String {
        return r'[.!?][\s]{1,2}(?=[A-Z])'
    }

    public func split_sentences(text: String): ArrayList<String> {
        let pattern = this.generate_split_sentences_pattern()
        let regex = Regex(#'${pattern}\s*'#{  // Add space consumer after split pattern
        let parts = regex.split(text)
        let result = ArrayList<String>()
        for (i, part) in parts.each() {
            if (i == parts.size - 1) {  // Last part keeps ending punctuation
                result.add(part)
            } else {  // Remove space before capital (from split)
                // Cangjie's regex might need trimming here
                result.add(part.trim())
            }
        }
        return result
    }

    public func validate_phone_number(phone_number: String): Bool {
        let pattern = this.generate_phone_number_pattern()
        return this.match_regex(pattern, phone_number)
    }

    public func extract_email(text: String): ArrayList<String> {
        let pattern = this.generate_email_pattern()
        return this.findall(pattern, text)
    }
}

class RPGCharacter {

    let name: String
    var hp: Int64
    var attack_power: Int64
    var defense: Int64
    var level: Int64
    var exp: Int64

    public init(name: String, hp: Int64, attack_power: Int64, defense: Int64, level!: Int64 = 1) {
        this.name = name
        this.hp = hp
        this.attack_power = attack_power
        this.defense = defense
        this.level = level
        this.exp = 0
    }

    public func attack(other_character: RPGCharacter): Unit {
        let damage = max(this.attack_power - other_character.defense, 1)
        other_character.hp -= damage
    }

    public func heal(): Int64 {
        this.hp += 10
        if (this.hp > 100) {
            this.hp = 100
        }
        return this.hp
    }

    public func gain_exp(amount: Int64): Unit {
        while (amount != 0) {
            let needed_for_next_level = this.level * 100 - this.exp
            if (amount >= needed_for_next_level) {
                if (this.level < 100) {
                    amount -= needed_for_next_level
                    this.exp = 0
                    this.level_up()
                } else {
                    amount = 0
                }
            } else {
                this.exp += amount
                amount = 0
            }
        }
    }

    public func level_up(): (Int64, Int64, Int64, Int64) {
        if (this.level < 100) {
            this.level += 1
            this.hp += 20
            this.attack_power += 5
            this.defense += 5
            return (this.level, this.hp, this.attack_power, this.defense)
        }
        return (this.level, this.hp, this.attack_power, this.defense)
    }

    public func is_alive(): Bool {
        return this.hp > 0
    }
}

