import std.collection.HashMap

class Server {
    let white_list: ArrayList<Int64>
    let send_struct: HashMap<String, Any>
    let receive_struct: HashMap<String, Any>

    public init() {
        this.white_list = ArrayList<Int64>()
        this.send_struct = HashMap<String, Any>()
        this.receive_struct = HashMap<String, Any>()
    }

    public func add_white_list(addr: Int64): Option<ArrayList<Int64>> {
        for (i in 0..this.white_list.size) {
            if (this.white_list[i] == addr) {
                return None<ArrayList<Int64>>()
            }
        }
        this.white_list.add(addr)
        return Some<ArrayList<Int64>>(this.white_list)
    }

    public func del_white_list(addr: Int64): Option<ArrayList<Int64>> {
        for (i in 0..this.white_list.size) {
            if (this.white_list[i] == addr) {
                this.white_list.remove(at: i)
                return Some<ArrayList<Int64>>(this.white_list)
            }
        }
        return None<ArrayList<Int64>>()
    }

    public func recv(info: HashMap<String, Any>): Any {
        let addr_opt = info["addr"]
        let content_opt = info["content"]

        match (addr_opt) {
            case None<Any>() => return false
            case Some<Any>(addr) => {
                match (content_opt) {
                    case None<Any>() => return false
                    case Some<Any>(content) => {
                        if (match (addr) {
                            case None<Int64>() => false
                            case Some<Int64>(a) => {
                                let contains = false
                                for (i in 0..this.white_list.size) {
                                    if (this.white_list[i] == a) {
                                        contains = true
                                        break
                                    }
                                }
                                contains
                            }
                        }) {
                            this.receive_struct["addr"] = addr
                            this.receive_struct["content"] = content
                            return match (content) {
                                case None<Any>() => false
                                case Some<Any>(c) => c
                            }
                        } else {
                            return false
                        }
                    }
                }
            }
        }
    }

    public func send(info: HashMap<String, Any>): Option<String> {
        let addr_opt = info["addr"]
        let content_opt = info["content"]

        match (addr_opt) {
            case None<Any>() => return Some<String>("info structure is not correct")
            case Some<Any>(addr) => {
                match (content_opt) {
                    case None<Any>() => return Some<String>("info structure is not correct")
                    case Some<Any>(content) => {
                        this.send_struct["addr"] = addr
                        this.send_struct["content"] = content
                        return None<String>()
                    }
                }
            }
        }
    }

    public func show(type_struct: String): Option<HashMap<String, Any>> {
        match (type_struct) {
            case "send" => {
                let result = HashMap<String, Any>()
                if (this.send_struct.size > 0) {
                    result["addr"] = this.send_struct["addr"]
                    result["content"] = this.send_struct["content"]
                }
                return Some<HashMap<String, Any>>(result)
            }
            case "receive" => {
                let result = HashMap<String, Any>()
                if (this.receive_struct.size > 0) {
                    result["addr"] = this.receive_struct["addr"]
                    result["content"] = this.receive_struct["content"]
                }
                return Some<HashMap<String, Any>>(result)
            }
            case _ => return None<HashMap<String, Any>>()
        }
    }
}

