    var quantity: Int64

    public init(price: Float64, quantity: Int64) {
        this.price = price
        this.quantity = quantity
    }

    public override operator func != (that: Item): Bool {
        return this.price != that.price || this.quantity != that.quantity
    }

    public override operator func == (that: Item): Bool {
        return this.price == that.price && this.quantity == that.quantity
    }
}

class ShoppingCart {
    let items: HashMap<String, Item>

    public init() {
        items = HashMap<String, Item>()
    }

    public func add_item(item: String, price: Float64, quantity!: Int64 = 1): Unit {
        // Check if item exists and update or add new item
        if (items.contains(key: item)) {
            var existing = items.get(key: item).getOrThrow()
            existing.price = price  // Override price (behavior matches Python example)
            existing.quantity = quantity
            items.add(key: item, value: existing)
        } else {
            items.add(key: item, value: Item(price: price, quantity: quantity))
        }
    }

    public func remove_item(item: String, quantity!: Int64 = 1): Unit {
        if (items.contains(key: item)) {
            var existing = items.get(key: item).getOrThrow()
            existing.quantity = max(of: 0, existing.quantity - quantity)  // Ensure quantity doesn't go negative
            if (existing.quantity == 0) {
                items.remove(key: item)
            } else {
                items.add(key: item, value: existing)
            }
        }
    }

    public func view_items(): HashMap<String, Item> {
        return items
    }

    public func total_price(): Float64 {
        var total: Float64 = 0.0
        for (itemStr, item in items) {
            total = total + (item.quantity * item.price)
        }
        return total
    }
}

