import std.collection.ArrayList
import std.random.Random

class Snake {
    var length: Int64
    let SCREEN_WIDTH: Int64
    let SCREEN_HEIGHT: Int64
    let BLOCK_SIZE: Int64
    var positions: ArrayList<ArrayList<Int64>>
    var score: Int64
    var food_position: ArrayList<Int64>

    public init(SCREEN_WIDTH: Int64, SCREEN_HEIGHT: Int64, BLOCK_SIZE: Int64, food_position: ArrayList<Int64>) {
        this.length = 1
        this.SCREEN_WIDTH = SCREEN_WIDTH
        this.SCREEN_HEIGHT = SCREEN_HEIGHT
        this.BLOCK_SIZE = BLOCK_SIZE
        let centerX = SCREEN_WIDTH / 2
        let centerY = SCREEN_HEIGHT / 2
        this.positions = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([centerX, centerY])])
        this.score = 0
        this.food_position = food_position
    }

    public func move(direction: ArrayList<Int64>): Unit {
        let cur = this.positions[0]
        let x = direction[0]
        let y = direction[1]
        let headX = (cur[0] + (x * this.BLOCK_SIZE)) % this.SCREEN_WIDTH
        let headY = (cur[1] + (y * this.BLOCK_SIZE)) % this.SCREEN_HEIGHT
        let newHead = ArrayList<Int64>([headX, headY])

        if (newHead[0] == this.food_position[0] && newHead[1] == this.food_position[1]) {
            this.eat_food()
        }

        // Check collision with body (excluding head)
        let bodyCollides = this.positions.size > 1 && (
            for (i in 1..this.positions.size:1) {
                if (this.positions[i][0] == newHead[0] && this.positions[i][1] == newHead[1]) {
                    break true
                }
            } false
        )

        if (bodyCollides) {
            this.reset()
        } else {
            this.positions.insert(0, newHead)
            if (this.positions.size > this.length) {
                this.positions.remove(at: this.positions.size - 1)
            }
        }
    }

    public func random_food_position(): Unit {
        while (true) {
            let rand = Random()
            let x = rand.nextInt(this.SCREEN_WIDTH / this.BLOCK_SIZE) * this.BLOCK_SIZE
            let y = rand.nextInt(this.SCREEN_HEIGHT / this.BLOCK_SIZE) * this.BLOCK_SIZE
            let newFood = ArrayList<Int64>([x, y])

            // Check if food position is on snake
            let onSnake = for (i in 0..this.positions.size:1) {
                if (this.positions[i][0] == newFood[0] && this.positions[i][1] == newFood[1]) {
                    break true
                }
            } false

            if (!onSnake) {
                this.food_position = newFood
                break
            }
        }
    }

    public func reset(): Unit {
        this.length = 1
        let centerX = this.SCREEN_WIDTH / 2
        let centerY = this.SCREEN_HEIGHT / 2
        this.positions = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([centerX, centerY])])
        this.score = 0
        this.random_food_position()
    }

    public func eat_food(): Unit {
        this.length += 1
        this.score += 100
        this.random_food_position()
    }
}

import std.collection.ArrayList
import std.regex.Regex
import std.unicode.UnicodeStringExtension

class SplitSentence {

    public func split_sentences(sentences_string: String): ArrayList<String> {
        // Regular expression pattern for sentence splitting
        let pattern = Regex(r'(?<!\w\.\w.)(?<![A-Z][a-z]\.)(?<=\.|\?)\s')
        let sentencesStr = pattern.split(sentences_string)
        let sentences = ArrayList<String>()
        for s in sentencesStr {
            sentences.add(s)
        }
        return sentences
    }

    public func count_words(sentence: String): Int64 {
        // Remove all non-alphabetic characters except spaces
        let pattern = Regex(r'[^a-zA-Z\s]')
        let cleaned = pattern.replaceAll(sentence, "")
        let words = cleaned.split()
        return words.size.toInt64()
    }

    public func process_text_file(sentences_string: String): Int64 {
        let sentences = this.split_sentences(sentences_string)
        var max_count: Int64 = 0
        for sentence in sentences {
            let count = this.count_words(sentence)
            if (count > max_count) {
                max_count = count
            }
        }
        return max_count
    }
}

