class SQLQueryBuilder {

    public static func select(table: String, columns!: ArrayList<String> = ArrayList<String>(['*']), where_condition!: Option<HashMap<String, String>> = None): String {
        var query: String = "SELECT "

        if (columns.size == 1 && columns[0] == "*") {
            query += "*"
        } else {
            var columns_str: String = ""
            for (i in 0..columns.size) {
                if (i > 0) {
                    columns_str += ", "
                }
                columns_str += columns[i]
            }
            query += columns_str
        }

        query += " FROM ${table}"

        if (where_condition ?? None) {
            let where_map = where_condition.getOrThrow()
            var where_clauses: ArrayList<String> = ArrayList<String>()
            for (k in where_map.keys()) {
                let v = where_map[k]
                where_clauses.add("${k}='${v}'")
            }
            query += " WHERE " + where_clauses.join(" AND ")
        }

        return query
    }

    public static func insert(table: String, data: HashMap<String, String>): String {
        var keys: ArrayList<String> = ArrayList<String>()
        var values: ArrayList<String> = ArrayList<String>()

        for (k in data.keys()) {
            keys.add(k)
            values.add("'" + data[k] + "'")
        }

        return "INSERT INTO ${table} (${keys.join(", ")}) VALUES (${values.join(", ")})"
    }

    public static func delete(table: String, where_condition!: Option<HashMap<String, String>> = None): String {
        var query: String = "DELETE FROM ${table}"

        if (where_condition ?? None) {
            let where_map = where_condition.getOrThrow()
            var where_clauses: ArrayList<String> = ArrayList<String>()
            for (k in where_map.keys()) {
                let v = where_map[k]
                where_clauses.add("${k}='${v}'")
            }
            query += " WHERE " + where_clauses.join(" AND ")
        }

        return query
    }

    public static func update(table: String, data: HashMap<String, String>, where_condition!: Option<HashMap<String, String>> = None): String {
        var set_clauses: ArrayList<String> = ArrayList<String>()

        for (k in data.keys()) {
            set_clauses.add("${k}='${data[k]}'")
        }

        var query: String = "UPDATE ${table} SET ${set_clauses.join(", ")}"

        if (where_condition ?? None) {
            let where_map = where_condition.getOrThrow()
            var where_clauses: ArrayList<String> = ArrayList<String>()
            for (k in where_map.keys()) {
                let v = where_map[k]
                where_clauses.add("${k}='${v}'")
            }
            query += " WHERE " + where_clauses.join(" AND ")
        }

        return query
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.math.abs
import std.sort.sort
import std.math.sqrt

class Statistics3 {
    public static func median(data: ArrayList<Int64>): Float64 {
        let sorted_data = data.clone()
        sort(sorted_data)
        let n = sorted_data.size
        if n % 2 == 1 {
            return Float64(sorted_data[n / 2])
        } else {
            return (Float64(sorted_data[n / 2 - 1]) + Float64(sorted_data[n / 2])) / 2.0
        }
    }

    public static func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        let counts = HashMap<Int64, Int64>()
        for value in data {
            let count = counts.get(value) ?? 0
            counts.add(value, count + 1)
        }
        let max_count = counts.reduce({max, pair => if (pair.value > max) { pair.value } else { max } }, 0)
        let mode_values = ArrayList<Int64>()
        for pair in counts {
            if pair.value == max_count {
                mode_values.add(pair.key)
            }
        }
        return mode_values
    }

    public static func correlation(x: ArrayList<Int64>, y: ArrayList<Int64>): Option<Float64> {
        let n = x.size
        if n != y.size {
            return None<Float64>()
        }

        let mean_x = mean(x) ?? 0.0
        let mean_y = mean(y) ?? 0.0

        var numerator: Float64 = 0.0
        var sum_x_sq: Float64 = 0.0
        var sum_y_sq: Float64 = 0.0

        for i in 0..n {
            let xi = Float64(x[i])
            let yi = Float64(y[i])
            numerator += (xi - mean_x) * (yi - mean_y)
            sum_x_sq += (xi - mean_x) * (xi - mean_x)
            sum_y_sq += (yi - mean_y) * (yi - mean_y)
        }

        let denominator = sqrt(sum_x_sq * sum_y_sq)
        if denominator == 0.0 {
            return None<Float64>()
        }
        return Some<Float64>(numerator / denominator)
    }

    public static func mean(data: ArrayList<Int64>): Option<Float64> {
        let n = data.size
        if n == 0 {
            return None<Float64>()
        }

        var sum: Int64 = 0
        for value in data {
            sum += value
        }
        return Some<Float64>(Float64(sum) / Float64(n))
    }

    public static func correlation_matrix(data: ArrayList<ArrayList<Int64>>): ArrayList<ArrayList<Float64>> {
        let n = data.size
        if n == 0 {
            return ArrayList<ArrayList<Float64>>()
        }
        let m = data[0].size
        let matrix = ArrayList<ArrayList<Float64>>()

        for i in 0..m {
            let row = ArrayList<Float64>()
            for j in 0..m {
                let column1 = ArrayList<Int64>()
                let column2 = ArrayList<Int64>()
                for k in 0..n {
                    column1.add(data[k][i])
                    column2.add(data[k][j])
                }
                let corr = correlation(column1, column2) ?? 0.0
                row.add(corr)
            }
            matrix.add(row)
        }
        return matrix
    }

    public static func standard_deviation(data: ArrayList<Int64>): Option<Float64> {
        let n = data.size
        if n < 2 {
            return None<Float64>()
        }
        let mean_value = mean(data) ?? 0.0
        var variance: Float64 = 0.0
        for value in data {
            variance += (Float64(value) - mean_value) * (Float64(value) - mean_value)
        }
        variance /= Float64(n - 1)
        return Some<Float64>(sqrt(variance))
    }

    public static func z_score(data: ArrayList<Int64>): Option<ArrayList<Float64>> {
        let mean_value = mean(data) ?? 0.0
        let std_deviation = standard_deviation(data) ?? 0.0
        if std_deviation == 0.0 {
            return None<ArrayList<Float64>>()
        }

        let result = ArrayList<Float64>()
        for value in data {
            result.add((Float64(value) - mean_value) / std_deviation)
        }
        return Some<ArrayList<Float64>>(result)
    }
}

