class StockPortfolioTracker {
    var portfolio: ArrayList<Stock>
    var cash_balance: Float64

    public init(cash_balance: Float64) {
        this.portfolio = ArrayList<Stock>()
        this.cash_balance = cash_balance
    }

    public func add_stock(stock: Stock): Unit {
        for (i in 0..portfolio.size) {
            let pf = portfolio[i]
            if (pf.name == stock.name) {
                portfolio[i].quantity += stock.quantity
                return
            }
        }
        portfolio.add(stock)
    }

    public func remove_stock(stock: Stock): Bool {
        for (i in 0..portfolio.size) {
            let pf = portfolio[i]
            if (pf.name == stock.name && pf.quantity >= stock.quantity) {
                portfolio[i].quantity -= stock.quantity
                if (portfolio[i].quantity == 0) {
                    portfolio.remove(at: i)
                }
                return true
            }
        }
        return false
    }

    public func buy_stock(stock: Stock): Bool {
        let cost = stock.price * stock.quantity
        if (cost > cash_balance) {
            return false
        } else {
            add_stock(stock: stock)
            cash_balance -= cost
            return true
        }
    }

    public func sell_stock(stock: Stock): Bool {
        if (!remove_stock(stock: stock)) {
            return false
        }
        cash_balance += stock.price * stock.quantity
        return true
    }

    public func calculate_portfolio_value(): Float64 {
        var total_value = cash_balance
        for (i in 0..portfolio.size) {
            let stock = portfolio[i]
            total_value += stock.price * stock.quantity
        }
        return total_value
    }

    public func get_portfolio_summary(): (Float64, ArrayList<HashMap<String, Any>>) {
        var summary = ArrayList<HashMap<String, Any>>()
        for (i in 0..portfolio.size) {
            let stock = portfolio[i]
            let value = get_stock_value(stock: stock)
            let entry = HashMap<String, Any>([
                ("name", stock.name),
                ("value", value)
            ])
            summary.add(entry)
        }
        let portfolio_value = calculate_portfolio_value()
        return (portfolio_value, summary)
    }

    public func get_stock_value(stock: Stock): Float64 {
        return stock.price * stock.quantity
    }
}

