class TicTacToe {

    let board: ArrayList<ArrayList<String>>
    var current_player: String

    public init(N!: Int64 = 3) {
        this.board = ArrayList<ArrayList<String>>()
        for (_ in 0..3) {
            let row = ArrayList<String>()
            for (_ in 0..N) {
                row.add(' ')
            }
            this.board.add(row)
        }
        this.current_player = 'X'
    }

    public func make_move(row: Int64, col: Int64): Bool {
        if (this.board.get(row) != None && this.board.get(row)!!.get(col) != None) {
            let current_cell = this.board.get(row)!!.get(col)
            if (current_cell == ' ') {
                this.board.get(row)!!.set(col, this.current_player)
                this.current_player = if (this.current_player == 'X') { 'O' } else { 'X' }
                return true
            }
        }
        return false
    }

    public func check_winner(): Option<String> {
        // Check rows
        for (i in 0..3) {
            if (let row = this.board.get(i)) {
                let cell0 = row.get(0)
                let cell1 = row.get(1)
                let cell2 = row.get(2)
                if (cell0 != None && cell1 != None && cell2 != None && 
                    cell0!! == cell1!! && cell1!! == cell2!! && cell0!! != ' ') {
                    return Some(cell0!!)
                }
            }
        }

        // Check columns
        for (j in 0..3) {
            let cell0 = this.board.get(0)?.get(j)
            let cell1 = this.board.get(1)?.get(j)
            let cell2 = this.board.get(2)?.get(j)
            if (cell0 != None && cell1 != None && cell2 != None && 
                cell0!! == cell1!! && cell1!! == cell2!! && cell0!! != ' ') {
                return Some(cell0!!)
            }
        }

        // Check diagonals
        let d1 = this.board.get(0)?.get(0)
        let d2 = this.board.get(1)?.get(1)
        let d3 = this.board.get(2)?.get(2)
        if (d1 != None && d2 != None && d3 != None && 
            d1!! == d2!! && d2!! == d3!! && d1!! != ' ') {
            return Some(d1!!)
        }

        let d4 = this.board.get(0)?.get(2)
        let d5 = this.board.get(1)?.get(1)
        let d6 = this.board.get(2)?.get(0)
        if (d4 != None && d5 != None && d6 != None && 
            d4!! == d5!! && d5!! == d6!! && d4!! != ' ') {
            return Some(d4!!)
        }

        return None<String>()
    }

    public func is_board_full(): Bool {
        for (i in 0..3) {
            if (let row = this.board.get(i)) {
                for (j in 0..3) {  // Hardcoded 3 since we're using 3x3 board for checks
                    if (row.get(j) == ' ') {
                        return false
                    }
                }
            }
        }
        return true
    }
}

