import std.math.numeric.Decimal
import std.math.numeric.round
import std.math.abs

class TriCalculator {

    let PI = 3.141592653589793

    public init() {}

    public func cos(x: Float64): Float64 {
        return round(this.taylor(x, 50), 10)
    }

    public func factorial(a: Int64): Decimal {
        var b: Decimal = 1
        var counter = a
        while (counter != 1) {
            b *= Decimal(counter)
            counter -= 1
        }
        return b
    }

    public func taylor(x: Float64, n: Int64): Float64 {
        var a: Float64 = 1.0
        let radian = x / 180.0 * PI
        var count = 1
        for (k in 1..n) {
            let power = Float64(2 * k)
            let numerator = radian ^^ power
            let denominator = this.factorial(Int64(power)).toFloat64()
            if (count % 2 != 0) {
                a -= numerator / denominator
            } else {
                a += numerator / denominator
            }
            count += 1
        }
        return a
    }

    public func sin(x: Float64): Float64 {
        let radian = x / 180.0 * PI
        var g: Float64 = 0.0
        var t: Float64 = radian
        var n: Int64 = 1
        while (abs(t) >= 1e-15) {
            g += t
            n += 1
            t = -t * radian * radian / Float64(2*n - 1) / Float64(2*n - 2)
        }
        return round(g, 10)
    }

    public func tan(x: Float64): Option<Float64> {
        let cos_val = this.cos(x)
        if (abs(cos_val - 0.0) > 0.000001) {
            let sin_val = this.sin(x)
            let result = sin_val / cos_val
            return Some<Float64>(round(result, 10))
        } else {
            return None<Float64>()
        }
    }
}

