class Parser {
    let expr: String
    var pos: Int64
    var ch: Rune

    public init(expr: String) {
        this.expr = expr
        this.pos = -1
        this.ch = r'x'
        this.next_char()
    }

    public func next_char(): Unit {
        this.pos += 1
        if (this.pos < this.expr.size) {
            this.ch = Rune(this.expr[this.pos])
        } else {
            this.ch = r'x'
        }
    }

    public func eat(char_to_eat: Rune): Bool {
        while (this.ch == r' ') {
            this.next_char()
        }
        if (this.ch == char_to_eat) {
            this.next_char()
            return true
        }
        return false
    }

    public func parse(): Int64 {
        let x = this.parse_expression()
        if (this.pos < this.expr.size) {
            throw Exception("Unexpected: ${this.ch}")
        }
        return x
    }

    public func parse_expression(): Int64 {
        var x = this.parse_term()
        while (true) {
            if (this.eat(r'+')) {
                x += this.parse_term()
            } else if (this.eat(r'-')) {
                x -= this.parse_term()
            } else {
                return x
            }
        }
        return x
    }

    public func parse_term(): Int64 {
        var x = this.parse_factor()
        while (true) {
            if (this.eat(r'*')) {
                x *= this.parse_factor()
            } else if (this.eat(r'/')) {
                x /= this.parse_factor()
            } else {
                return x
            }
        }
        return x
    }

    public func parse_factor(): Int64 {
        if (this.eat(r'+')) {
            return this.parse_factor()
        }
        if (this.eat(r'-')) {
            return -this.parse_factor()
        }

        var x = 0
        var start_pos = this.pos

        if (this.eat(r'(')) {
            x = this.parse_expression()
            this.eat(r')')
        } else if (this.ch != r'x' && (this.ch.isAsciiNumber() || this.ch == r'.')) {
            while (this.ch != r'x' && (this.ch.isAsciiNumber() || this.ch == r'.')) {
                this.next_char()
            }
            x = Int64.parse(this.expr[start_pos..this.pos])
        } else {
            if (this.ch != r'x') {
                throw Exception("Unexpected: ${this.ch}")
            } else {
                throw Exception("Unexpected end of expression")
            }
        }
        return x
    }
}

class TwentyFourPointGame {
    var nums: ArrayList<Int64>
    var random: Random

    public init() {
        this.nums = ArrayList<Int64>()
        this.random = Random()
    }

    public func _generate_cards(): Unit {
        this.nums.clear()
        for (i in 0..4:1) {
            this.nums.add(this.random.nextInt(1, 10))
        }
    }

    public func get_my_cards(): ArrayList<Int64> {
        this._generate_cards()
        return this.nums
    }

    public func answer(expression: String): Bool {
        if (expression == "pass") {
            return true // In Cangjie, we just return true here (Python returns new cards)
        }

        var statistic: HashMap<Rune, Int64> = HashMap<Rune, Int64>()
        for (i in 0..expression.size:1) {
            let c = Rune(expression[i])
            if (c.isAsciiNumber()) {
                let num = Int64.parse(c.toString())
                var count = statistic.get(c).getOrThrow(0)
                count += 1
                statistic.put(c, count)
            }
        }

        var nums_used = statistic.copy()

        for (i in 0..this.nums.size:1) {
            let num = this.nums.get(i)
            let num_char = Rune(num.toString()[0])
            var count = nums_used.get(num_char).getOrThrow(0)
            if (count <= 0) {
                return false
            }
            count -= 1
            nums_used.put(num_char, count)
        }

        if (nums_used.values().all({v: Int64 => v == 0})) {
            return this.evaluate_expression(expression)
        } else {
            return false
        }
    }

    public func evaluate_expression(expression: String): Bool {
        try {
            let parser = Parser(expr: expression)
            let result = parser.parse()
            return result == 24
        } catch {
            return false
        }
    }
}

