class URLHandler {
    let url: String

    public init(url: String) {
        this.url = url
    }

    public func get_scheme(): Option<String> {
        let scheme_end = url.find("://")
        if (scheme_end != -1) {
            return Some<String>(url[:scheme_end])
        }
        return None<String>
    }

    public func get_host(): Option<String> {
        let scheme_end = url.find("://")
        if (scheme_end != -1) {
            let url_without_scheme = url[scheme_end + 3:]
            let host_end = url_without_scheme.find("/")
            if (host_end != -1) {
                return Some<String>(url_without_scheme[:host_end])
            }
            return Some<String>(url_without_scheme)
        }
        return None<String>
    }

    public func get_path(): Option<String> {
        let scheme_end = url.find("://")
        if (scheme_end != -1) {
            let url_without_scheme = url[scheme_end + 3:]
            let host_end = url_without_scheme.find("/")
            if (host_end != -1) {
                return Some<String>(url_without_scheme[host_end:])
            }
        }
        return None<String>
    }

    public func get_query_params(): Option<HashMap<String, String>> {
        let query_start = url.find("?")
        let fragment_start = url.find("#")
        if (query_start != -1) {
            let end_index = if (fragment_start != -1) { fragment_start } else { url.size }
            let query_string = url[query_start + 1:end_index]
            if (query_string.size > 0) {
                let param_pairs = query_string.split("&")
                var params = HashMap<String, String>()
                for (pair in param_pairs) {
                    let key_value = pair.split("=")
                    if (key_value.size == 2) {
                        params.add(key_value[0], key_value[1])
                    }
                }
                return Some<HashMap<String, String>>(params)
            }
        }
        return None<HashMap<String, String>>
    }

    public func get_fragment(): Option<String> {
        let fragment_start = url.find("#")
        if (fragment_start != -1) {
            return Some<String>(url[fragment_start + 1:])
        }
        return None<String>
    }
}

