class UrlPath {
    let segments: ArrayList<String>
    var with_end_tag: Bool

    public init() {
        this.segments = ArrayList<String>()
        this.with_end_tag = false
    }

    public func add(segment: String): Unit {
        let fixed_segment = UrlPath.fix_path(segment: segment)
        this.segments.add(fixed_segment)
    }

    public func parse(path: String, charset: String = "UTF-8"): Unit {
        if (path.isEmpty()) {
            return
        }

        if (path.endsWith("/")) {
            this.with_end_tag = true
        }

        let fixed_path = UrlPath.fix_path(path: path)
        if (fixed_path.isEmpty()) {
            return
        }

        let split = fixed_path.split("/")
        for (seg in split) {
            // In Cangjie, we'd need to use the URL decoding function from std.net.url
            // Assuming decodeURIComponent is available
            let decoded_seg = urldecode(seg, charset: charset) // Hypothetical function
            this.segments.add(decoded_seg)
        }
    }

    public static func fix_path(path: String): String {
        if (path.isEmpty()) {
            return ""
        }
        let stripped = path.strip("/")
        return stripped
    }
}

import std.collection.HashMap
