class VectorUtil {

    public static func normalize(vector: ArrayList<Float64>): ArrayList<Float64> {
        let norm = sqrt(vector.reduce(0.0, { acc, v => acc + pow(v, 2.0) }))
        if (norm == 0.0) {
            return vector
        }
        let normalized = ArrayList<Float64>()
        for (i in 0..vector.size) {
            normalized.add(vector[i] / norm)
        }
        return normalized
    }

    public static func similarity(vector_1: ArrayList<Float64>, vector_2: ArrayList<Float64>): Float64 {
        let u = normaloze(vector_1)
        let v = normalize(vector_2)

        let dot_product = u.reduce(0.0, { acc, (u_i, i) => 
            acc + u_i * v[i] 
        }) // Note: Cangjie lacks direct index in reduce, requires alternative
        // Simplified version (assuming vectors are same length):
        var dot = 0.0
        for (i in 0..u.size) {
            dot += u[i] * v[i]
        }
        return dot
    }

    public static func cosine_similarities(vector_1: ArrayList<Float64>, vectors_all: ArrayList<ArrayList<Float64>>): ArrayList<Float64> {
        let norm_v1 = sqrt(vector_1.reduce(0.0, { acc, v => acc + pow(v, 2.0) }))
        let all_norms = ArrayList<Float64>()
        for (vec in vectors_all) {
            all_norms.add(sqrt(vec.reduce(0.0, { acc, v => acc + pow(v, 2.0) })))
        }

        let dot_products = ArrayList<Float64>()
        for (vec in vectors_all) {
            var dot = 0.0
            for (i in 0..vec.size) {
                dot += vector_1[i] * vec[i]
            }
            dot_products.add(dot)
        }

        let similarities = ArrayList<Float64>()
        for (i in 0..dot_products.size) {
            similarities.add(dot_products[i] / (norm_v1 * all_norms[i]))
        }
        return similarities
    }

    public static func average_vector(vectors: ArrayList<ArrayList<Float64>>): ArrayList<Float64> {
        if (vectors.size == 0) {
            return ArrayList<Float64>()
        }
        let dim = vectors[0].size
        let avg = ArrayList<Float64>(ArrayList<Float64>.fill(dim, 0.0))

        for (vec in vectors) {
            for (i in 0..dim) {
                avg[i] += vec[i]
            }
        }

        for (i in 0..dim) {
            avg[i] /= vectors.size as Float64
        }
        return avg
    }

    public static func n_similarity(vector_list_1: ArrayList<ArrayList<Float64>>, vector_list_2: ArrayList<ArrayList<Float64>>): Float64 {
        if (vector_list_1.size == 0 || vector_list_2.size == 0) {
            // Cangjie doesn't have built-in ZeroDivisionError, so we panic or return default
            return 0.0 // Simplified for demo
        }

        let avg1 = average_vector(vector_list_1)
        let avg2 = average_vector(vector_list_2)

        let norm1 = sqrt(avg1.reduce(0.0, { acc, v => acc + pow(v, 2.0) }))
        let norm2 = sqrt(avg2.reduce(0.0, { acc, v => acc + pow(v, 2.0) }))

        var dot = 0.0
        for (i in 0..avg1.size) {
            dot += avg1[i] * avg2[i]
        }

        return dot / (norm1 * norm2)
    }

    public static func compute_idf_weight_dict(total_num: Int64, number_dict: HashMap<String, Float64>): HashMap<String, Float64> {
        let index_2_key_map = HashMap<Int64, String>()
        let count_list = ArrayList<Float64>()
        var index: Int64 = 0

        for (key, count) in number_dict.entries() {
            index_2_key_map.add(index, key)
            count_list.add(count)
            index += 1
        }

        let a = ArrayList<Float64>()
        for (count in count_list) {
            a.add(log((total_num + 1) as Float64 / (count + 1)))
        }

        let result = HashMap<String, Float64>()
        for (i in 0..a.size) {
            let key = index_2_key_map.get(i) ?? "" // Shouldn't happen
            result.add(key, a[i])
        }
        return result
    }
}

