        this.balance += amount
        return this.balance
    }

    public func purchase_item(item_name: String): Option<Float64> {
        let item_option = this.inventory.get(key: item_name)
        match (item_option) {
            case Some<Product>(let item) => {
                if (item.quantity > 0 && this.balance >= item.price) {
                    this.balance -= item.price
                    item.quantity -= 1
                    return Some<Float64>(this.balance)
                } else {
                    return None<Float64>
                }
            }
            case _ => return None<Float64>
        }
    }

    public func restock_item(item_name: String, quantity: Int64): Bool {
        let item_option = this.inventory.get(key: item_name)
        match (item_option) {
            case Some<Product>(let item) => {
                item.quantity += quantity
                return true
            }
            case _ => return false
        }
    }

    public func display_items(): Option<String> {
        if (this.inventory.size == 0) {
            return None<String>
        } else {
            var items_list = ArrayList<String>()
            let names = this.inventory.keys()
            for (name in names) {
                let item = this.inventory[name]!
                let item_str = "${name} - $${item.price} [${item.quantity}]"
                items_list.add(item_str)
            }
            return Some<String>(items_list.join("\n"))
        }
    }
}

import std.collection.HashMap

class Product <: Equatable<Product> {

    let name: String
    var quantity: Int64

    public init(name: String, quantity: Int64) {
        this.name = name
        this.quantity = quantity
    }

    public override operator func != (that: Product): Bool {
        return this.name != that.name || this.quantity != that.quantity
    }

    public override operator func == (that: Product): Bool {
        return this.name == that.name && this.quantity == that.quantity
    }
}

class Order <: Equatable<Order> {

    let product_id: Int64
    let quantity: Int64
    var status: String

    public init(product_id: Int64, quantity: Int64, status: String) {
        this.product_id = product_id
        this.quantity = quantity
        this.status = status
    }

    public override operator func != (that: Order): Bool {
        return this.product_id != that.product_id || this.quantity != that.quantity || this.status != that.status
    }

    public override operator func == (that: Order): Bool {
        return this.product_id == that.product_id && this.quantity == that.quantity && this.status == that.status
    }
}

class Warehouse {

    let inventory: HashMap<Int64, Product>
    let orders: HashMap<Int64, Order>

    public init() {
        this.inventory = HashMap<Int64, Product>()
        this.orders = HashMap<Int64, Order>()
    }

    public func add_product(product_id: Int64, name: String, quantity: Int64): Unit {
        if (this.inventory.contains(key: product_id)) {
            let product = this.inventory[product_id]
            product.quantity += quantity
        } else {
            this.inventory.add(key: product_id, value: Product(name: name, quantity: quantity))
        }
    }

    public func update_product_quantity(product_id: Int64, quantity: Int64): Unit {
        if (this.inventory.contains(key: product_id)) {
            let product = this.inventory[product_id]
            product.quantity += quantity
        }
    }

    public func get_product_quantity(product_id: Int64): Option<Int64> {
        if (this.inventory.contains(key: product_id)) {
            let product = this.inventory[product_id]
            return Some<Int64>(product.quantity)
        } else {
            return None<Int64>
        }
    }

    public func create_order(order_id: Int64, product_id: Int64, quantity: Int64): Bool {
        let quantity_option = this.get_product_quantity(product_id: product_id)
        if (quantity_option is Some<Int64> && quantity_option.getOrThrow() >= quantity) {
            this.update_product_quantity(product_id: product_id, quantity: -quantity)
            this.orders.add(key: order_id, value: Order(product_id: product_id, quantity: quantity, status: "Shipped"))
            return true
        } else {
            return false
        }
    }

    public func change_order_status(order_id: Int64, status: String): Bool {
        if (this.orders.contains(key: order_id)) {
            let order = this.orders[order_id]
            order.status = status
            return true
        } else {
            return false
        }
    }

    public func track_order(order_id: Int64): Option<String> {
        if (this.orders.contains(key: order_id)) {
            let order = this.orders[order_id]
            return Some<String>(order.status)
        } else {
            return None<String>
        }
    }
}

import std.collection.HashMap
import std.collection.* // For HashMap operations

class Weather {
    let weather: String
    let temperature: Float64
    let temperature_units: String

    public init(weather: String, temperature: Float64, temperature_units: String) {
        this.weather = weather
        this.temperature = temperature
        this.temperature_units = temperature_units
    }
}

class WeatherSystem {
    var temperature: Float64
    var weather: String
    var city: String
    var weather_list: HashMap<String, Weather>

    public init(city: String) {
        this.temperature = Float64.NaN
        this.weather = ""
        this.city = city
        this.weather_list = HashMap<String, Weather>()
    }

    public func query(weather_list: HashMap<String, Weather>, tmp_units!: String = "celsius"): Option<(Float64, String)> {
        this.weather_list = weather_list
        if (!this.weather_list.contains(this.city)) {
            return None<(Float64, String)>()
        }

        let city_weather = this.weather_list[this.city]
        this.temperature = city_weather.temperature
        this.weather = city_weather.weather

        if (city_weather.temperature_units != tmp_units) {
            if (tmp_units == "celsius") {
                let converted_temp = this.fahrenheit_to_celsius()
                return Some<(Float64, String)>((converted_temp, this.weather))
            } else if (tmp_units == "fahrenheit") {
                let converted_temp = this.celsius_to_fahrenheit()
                return Some<(Float64, String)>((converted_temp, this.weather))
            }
        }

        return Some<(Float64, String)>((this.temperature, this.weather))
    }

    public func set_city(city: String): Unit {
        this.city = city
    }

    public func celsius_to_fahrenheit(): Float64 {
        return (this.temperature * 9.0 / 5.0) + 32.0
    }

    public func fahrenheit_to_celsius(): Float64 {
        return (this.temperature - 32.0) * 5.0 / 9.0
    }
}

import std.collection.HashMap
import std.collection.ArrayList
import std.math.pow

class Words2Numbers {

    let numwords: HashMap<String, (Int64, Int64)>
    let units: ArrayList<String>
    let tens: ArrayList<String>
    let scales: ArrayList<String>
    let ordinal_words: HashMap<String, Int64>
    let ordinal_endings: ArrayList<(String, String)>

    public init() {
        this.numwords = HashMap<String, (Int64, Int64)>()
        this.units = ArrayList<String>(["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"])
        this.tens = ArrayList<String>(["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"])
        this.scales = ArrayList<String>(["hundred", "thousand", "million", "billion", "trillion"])

        this.numwords["and"] = (1, 0)
        for (idx in 0..<this.units.size) {
            this.numwords[this.units[idx]] = (1, idx)
        }
        for (idx in 0..<this.tens.size) {
            this.numwords[this.tens[idx]] = (1, idx * 10)
        }
        for (idx in 0..<this.scales.size) {
            let scale_value = if (idx * 3 == 0) {
                100
            } else {
                Int64(pow(Int64(10), idx * 3))
            }
            this.numwords[this.scales[idx]] = (scale_value, 0)
        }

        this.ordinal_words = HashMap<String, Int64>([("first", 1), ("second", 2), ("third", 3), ("fifth", 5), ("eighth", 8), ("ninth", 9), ("twelfth", 12)])
        this.ordinal_endings = ArrayList<(String, String)>([("ieth", "y"), ("th", "")])
    }

    public func text2int(textnum: String): String {
        var processed = textnum.replace("-", " ")

        var current: Int64 = 0
        var result: Int64 = 0
        var curstring = ""
        var onnumber = false

        let words = processed.split()
        for (i in 0..<words.size) {
            let word = words[i]

            if (this.ordinal_words.contains(word)) {
                let increment = this.ordinal_words[word]!
                current = current * 1 + increment
                onnumber = true
            } else {
                var modified_word = word
                var matched = false

                for (end, repl) in this.ordinal_endings {
                    if (modified_word.endsWith(end)) {
                        let start = modified_word.size - end.size
                        modified_word = modified_word.substring(0, start) + repl
                        matched = true
                        break
                    }
                }

                if (!this.numwords.contains(modified_word)) {
                    if (onnumber) {
                        curstring += (result + current).toString() + " "
                    }
                    curstring += modified_word + " "
                    result = 0
                    current = 0
                    onnumber = false
                } else {
                    let (scale, increment) = this.numwords[modified_word]!
                    current = current * scale + increment
                    if (scale > 100) {
                        result += current
                        current = 0
                    }
                    onnumber = true
                }
            }
        }

        if (onnumber) {
            curstring += (result + current).toString()
        }

        return curstring.trim()
    }

    public func is_valid_input(textnum: String): Bool {
        var processed = textnum.replace("-", " ")

        let words = processed.split()
        for (i in 0..<words.size) {
            let word = words[i]

            if (this.ordinal_words.contains(word)) {
                continue
            } else {
                var modified_word = word
                var matched = false

                for (end, repl) in this.ordinal_endings {
                    if (modified_word.endsWith(end)) {
                        let start = modified_word.size - end.size
                        modified_word = modified_word.substring(0, start) + repl
                        matched = true
                        break
                    }
                }

                if (!this.numwords.contains(modified_word)) {
                    return false
                }
            }
        }

        return true
    }
}
